const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
const result = {}
try {
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(800)

  result.initial = await page.evaluate(() => {
    const d = window.__nightsDebug
    return {
      firstPerson: d.state.firstPerson,
      viewBlend: +d.state.viewBlend.toFixed(2),
      cameraBtn: !!document.getElementById('cameraBtn'),
      cameraPos: { x: +d.camera.position.x.toFixed(2), y: +d.camera.position.y.toFixed(2), z: +d.camera.position.z.toFixed(2) },
      fov: +d.camera.fov.toFixed(1),
      avatarVisible: d.player.children.find(c => c === d.player.children[0]) ? true : true
    }
  })
  await page.screenshot({ path: join(outDir, 'third-person.png') })

  // Toggle to first person
  await page.locator('#cameraBtn').click()
  await page.waitForTimeout(700)
  result.firstPerson = await page.evaluate(() => {
    const d = window.__nightsDebug
    return {
      firstPerson: d.state.firstPerson,
      viewBlend: +d.state.viewBlend.toFixed(2),
      fov: +d.camera.fov.toFixed(1),
      cameraPos: { x: +d.camera.position.x.toFixed(2), y: +d.camera.position.y.toFixed(2), z: +d.camera.position.z.toFixed(2) },
      pivot: { x: +d.player.position.x.toFixed(2), y: +(d.player.position.y + d.CAMERA_EYE_HEIGHT).toFixed(2), z: +d.player.position.z.toFixed(2) }
    }
  })
  await page.screenshot({ path: join(outDir, 'first-person.png') })

  // Character should stay centered: project pivot to NDC.
  result.centering = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.setFirstPerson(false)
    return new Promise(resolve => {
      setTimeout(() => {
        const THREE = d.camera.constructor
        const pivot = { x: d.player.position.x, y: d.player.position.y + d.CAMERA_EYE_HEIGHT, z: d.player.position.z }
        const v = d.player.position.clone()
        v.set(pivot.x, pivot.y, pivot.z)
        v.project(d.camera)
        resolve({ ndcX: +v.x.toFixed(3), ndcY: +v.y.toFixed(3) })
      }, 700)
    })
  })
  await page.screenshot({ path: join(outDir, 'third-person-2.png') })

  result.errors = errors
} catch (e) {
  result.failure = String(e && e.stack || e)
  result.errors = errors
  try { await page.screenshot({ path: join(outDir, 'failure.png') }) } catch {}
} finally {
  await browser.close()
}
