const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
const result = {}
const shot = async (name) => { await page.screenshot({ path: join(outDir, name + '.png') }) }
try {
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(700)

  // Equip axe and go first-person.
  await page.locator('#axeSlot').click()
  await page.waitForTimeout(500)
  await page.locator('#cameraBtn').click()
  await page.waitForTimeout(800)
  await shot('fp-axe-idle')

  // Mid swing.
  await page.evaluate(() => { const d = window.__nightsDebug; d.state.attackCooldown = 0; d.attack() })
  await page.waitForTimeout(130)
  await shot('fp-axe-swing')

  // Third person with axe.
  await page.waitForTimeout(600)
  await page.locator('#cameraBtn').click()
  await page.waitForTimeout(800)
  await shot('tp-axe')

  result.viewState = await page.evaluate(() => {
    const d = window.__nightsDebug
    return {
      firstPerson: d.state.firstPerson,
      blend: +d.state.viewBlend.toFixed(2),
      fov: +d.camera.fov.toFixed(1),
      camY: +d.camera.position.y.toFixed(2),
      groundY: +d.getGroundHeight(d.camera.position.x, d.camera.position.z).toFixed(2),
      avatarVisible: d.camera.parent ? true : true
    }
  })

  // Pitch clamp: dispatch a big upward drag on right half.
  const drag = async (id, from, to, steps = 12) => {
    await page.evaluate(({ id, from, to, steps }) => {
      const fire = (type, x, y) => window.dispatchEvent(new PointerEvent(type, {
        pointerId: id, pointerType: 'touch', clientX: x, clientY: y, bubbles: true, cancelable: true, isPrimary: id === 1
      }))
      fire('pointerdown', from.x, from.y)
      for (let i = 1; i <= steps; i++) {
        fire('pointermove', from.x + (to.x - from.x) * i / steps, from.y + (to.y - from.y) * i / steps)
      }
      fire('pointerup', to.x, to.y)
    }, { id, from, to, steps })
  }

  result.pitchBefore = await page.evaluate(() => +window.__nightsDebug.state.cameraPitch.toFixed(3))
  await drag(11, { x: 700, y: 320 }, { x: 700, y: 40 })
  await page.waitForTimeout(150)
