import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const outDir = '/tmp/opencode/browser-test/interact'
mkdirSync(outDir, { recursive: true })
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
const result = {}
const shot = async (name) => { await page.screenshot({ path: join(outDir, name + '.png') }) }

// Screen position of a world point.
const screenOf = (expr) => page.evaluate((expr) => {
  const d = window.__nightsDebug
  const p = eval(expr)
  const v = p.clone().project(d.camera)
  return { x: (v.x + 1) / 2 * window.innerWidth, y: (-v.y + 1) / 2 * window.innerHeight, behind: v.z > 1 }
}, expr)

// Real-ish tap via synthetic pointer events.
const tapAt = (x, y, id = 99) => page.evaluate(({ x, y, id }) => {
  const fire = (type) => window.dispatchEvent(new PointerEvent(type, {
    pointerId: id, pointerType: 'touch', clientX: x, clientY: y, bubbles: true, cancelable: true, isPrimary: true
  }))
  fire('pointerdown'); fire('pointerup')
}, { x, y, id })

const toast = () => page.evaluate(() => document.getElementById('toast').textContent.trim())
const placePlayer = (x, z, yaw) => page.evaluate(({ x, z, yaw }) => {
  const d = window.__nightsDebug
  d.player.position.set(x, d.getGroundHeight(x, z), z)
  d.state.cameraYaw = yaw
  d.state.cameraPitch = 0
  d.state.cameraInitialized = false
  d.state.attackCooldown = 0
  d.state.interactCooldown = 0
}, { x, z, yaw })

try {
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(600)

  // ---------- Machine tap ----------
  await placePlayer(3.4, 1.6, Math.PI)
  await page.waitForTimeout(400)
  const machineScreen = await page.evaluate(() => {
    const d = window.__nightsDebug
    const v = d.machine.position.clone(); v.y += 1.2
    v.project(d.camera)
    return { x: (v.x + 1) / 2 * innerWidth, y: (-v.y + 1) / 2 * innerHeight }
  })
  await tapAt(machineScreen.x, machineScreen.y, 41)
  await page.waitForTimeout(350)
  result.machineOpened = await page.evaluate(() => window.__nightsDebug.state.machineOpen)
  await shot('machine-tap')
  await page.evaluate(() => window.__nightsDebug.closeMachinePanel())
  await page.waitForTimeout(250)

  // ---------- Tree tap (axe) ----------
  await page.evaluate(() => { const d = window.__nightsDebug; d.equipTool('axe') })
  const treeInfo = await page.evaluate(() => {
    const d = window.__nightsDebug
    const t = d.treeData.find(t => t.visible && t.userData.choppable)
    const yaw = Math.atan2(t.position.x - d.player.position.x, t.position.z - d.player.position.z)
    return { x: t.position.x, z: t.position.z, yaw, hits: t.userData.hits, index: d.treeData.indexOf(t),
      px: t.position.x - Math.sin(yaw) * 2.3, pz: t.position.z - Math.cos(yaw) * 2.3 }
  })
  await placePlayer(treeInfo.px, treeInfo.pz, treeInfo.yaw)
  await page.waitForTimeout(400)
  const treeScreen = await page.evaluate((idx) => {
    const d = window.__nightsDebug
    const t = d.treeData[idx]
    const v = t.position.clone(); v.y += 1.1
    v.project(d.camera)
    return { x: (v.x + 1) / 2 * innerWidth, y: (-v.y + 1) / 2 * innerHeight }
  }, treeInfo.index)
  await tapAt(treeScreen.x, treeScreen.y, 42)
  await page.waitForTimeout(350)
  result.treeHitsBefore = treeInfo.hits
  result.treeHitsAfter = await page.evaluate((idx) => window.__nightsDebug.treeData[idx].userData.hits, treeInfo.index)
  result.treeToast = await toast()
  await shot('tree-tap')

  // ---------- Too far ----------
  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.playerFacing = 0
    const x = d.player.position.x, z = d.player.position.z
    d.spawnGroundItem('wood', x + Math.sin(d.state.cameraYaw) * 7, z + Math.cos(d.state.cameraYaw) * 7, { startY: 0.4, pickupDelay: 0 })
  })
  await page.waitForTimeout(600)
  const farScreen = await page.evaluate(() => {
    const d = window.__nightsDebug
    const item = d.groundItems[d.groundItems.length - 1]
    const v = item.mesh.position.clone(); v.y += 0.2
    v.project(d.camera)
    return { x: (v.x + 1) / 2 * innerWidth, y: (-v.y + 1) / 2 * innerHeight, behind: v.z > 1 }
  })
  result.farScreen = farScreen
  await tapAt(farScreen.x, farScreen.y, 43)
  await page.waitForTimeout(300)
  result.farToast = await toast()

  // ---------- Ground item pickup ----------
  const beforePick = await page.evaluate(() => window.__nightsDebug.carriedItems.length)
  await page.evaluate(() => {
    const d = window.__nightsDebug
    const x = d.player.position.x, z = d.player.position.z
    d.spawnGroundItem('wood', x + Math.sin(d.state.cameraYaw) * 1.6, z + Math.cos(d.state.cameraYaw) * 1.6, { startY: 0.4, pickupDelay: 0 })
  })
  await page.waitForTimeout(700)
  const itemScreen = await page.evaluate(() => {
    const d = window.__nightsDebug
    const item = d.groundItems[d.groundItems.length - 1]
    const v = item.mesh.position.clone(); v.y += 0.15
    v.project(d.camera)
    return { x: (v.x + 1) / 2 * innerWidth, y: (-v.y + 1) / 2 * innerHeight }
  })
  await tapAt(itemScreen.x, itemScreen.y, 44)
  await page.waitForTimeout(350)
  result.pickupBefore = beforePick
  result.pickupAfter = await page.evaluate(() => window.__nightsDebug.carriedItems.length)
  result.pickupToast = await toast()
  await shot('pickup-tap')

  // ---------- Button tap must not interact ----------
  const itemsBeforeBtn = await page.evaluate(() => window.__nightsDebug.carriedItems.length)
  await page.locator('#axeSlot').click()
  await page.waitForTimeout(250)
  result.buttonInteraction = {
    carriedBefore: itemsBeforeBtn,
    carriedAfter: await page.evaluate(() => window.__nightsDebug.carriedItems.length),
    equipped: await page.evaluate(() => window.__nightsDebug.state.equippedTool)
  }

  // ---------- Camera collision ----------
  const collision = await page.evaluate(() => {
    const d = window.__nightsDebug
    const t = d.treeData.find(t => t.visible)
    // Stand just beside the tree, camera pointing away so the tree sits behind the pivot.
    const yaw = Math.atan2(d.player.position.x - t.position.x, d.player.position.z - t.position.z)
    d.player.position.set(t.position.x + Math.sin(yaw) * 1.0, d.getGroundHeight(t.position.x, t.position.z), t.position.z + Math.cos(yaw) * 1.0)
    // Camera looks from the player toward the tree => tree is in front, camera behind.
    d.state.cameraYaw = yaw
    d.state.cameraPitch = 0
    d.state.cameraInitialized = false
    return { tree: { x: t.position.x, z: t.position.z }, yaw }
  })
  await page.waitForTimeout(600)
  result.collisionDistance = await page.evaluate(() => {
    const d = window.__nightsDebug
    const pivot = d.player.position.clone(); pivot.y += d.CAMERA_EYE_HEIGHT
    return +d.camera.position.distanceTo(pivot).toFixed(2)
  })
  await shot('collision')

  // ---------- Multi-touch: joystick + camera ----------
  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.player.position.set(0, d.getGroundHeight(0, 6), 6)
    d.state.cameraYaw = 0
    d.state.cameraPitch = 0
    d.state.joystick.x = 0; d.state.joystick.y = 0
  })
  await page.waitForTimeout(350)
  const joystickBox = await page.locator('#joystickZone').boundingBox()
  const client = await page.context().newCDPSession(page)
  const jx = joystickBox.x + joystickBox.width / 2
  const jy = joystickBox.y + joystickBox.height / 2
  const posBefore = await page.evaluate(() => ({ x: window.__nightsDebug.player.position.x, z: window.__nightsDebug.player.position.z, yaw: window.__nightsDebug.state.cameraYaw }))
  await client.send('Input.dispatchTouchEvent', {
    type: 'touchStart',
    touchPoints: [{ x: jx, y: jy, id: 1 }, { x: 640, y: 180, id: 2 }]
  })
  await client.send('Input.dispatchTouchEvent', {
    type: 'touchMove',
    touchPoints: [{ x: jx, y: jy - 40, id: 1 }, { x: 720, y: 180, id: 2 }]
  })
  await page.waitForTimeout(600)
  result.multiTouch = await page.evaluate(() => ({
    joystick: { x: +window.__nightsDebug.state.joystick.x.toFixed(2), y: +window.__nightsDebug.state.joystick.y.toFixed(2), active: window.__nightsDebug.state.joystick.active }
  }))
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] })
  await page.waitForTimeout(250)
  const posAfter = await page.evaluate(() => ({ x: window.__nightsDebug.player.position.x, z: window.__nightsDebug.player.position.z, yaw: window.__nightsDebug.state.cameraYaw }))
  result.multiTouch.moved = +Math.hypot(posAfter.x - posBefore.x, posAfter.z - posBefore.z).toFixed(2)
  result.multiTouch.yawChanged = +(posAfter.yaw - posBefore.yaw).toFixed(3)
  result.multiTouch.joystickReleased = await page.evaluate(() => !window.__nightsDebug.state.joystick.active)
  await shot('multitouch')

  // ---------- View memory across reload ----------
  await page.evaluate(() => window.__nightsDebug.setFirstPerson(true, false))
  await page.reload({ waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  result.rememberedFirst = await page.evaluate(() => {
    const d = window.__nightsDebug
    return { firstPerson: d.state.firstPerson, blend: d.state.viewBlend, btnPressed: document.getElementById('cameraBtn').getAttribute('aria-pressed') }
  })
  await page.evaluate(() => window.__nightsDebug.setFirstPerson(false, false))
  await page.reload({ waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  result.rememberedThird = await page.evaluate(() => window.__nightsDebug.state.firstPerson)

  result.errors = errors
} catch (e) {
  result.failure = String(e && e.stack || e)
  result.errors = errors
  try { await shot('failure') } catch {}
} finally {
  await browser.close()
}
