import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const outDir = '/tmp/opencode/browser-test/interact2'
mkdirSync(outDir, { recursive: true })
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
const result = {}
const shot = async (name) => { await page.screenshot({ path: join(outDir, name + '.png') }) }
const tapAt = (x, y, id = 99) => page.evaluate(({ x, y, id }) => {
  const fire = (type) => window.dispatchEvent(new PointerEvent(type, {
    pointerId: id, pointerType: 'touch', clientX: x, clientY: y, bubbles: true, cancelable: true, isPrimary: true
  }))
  fire('pointerdown'); fire('pointerup')
}, { x, y, id })
const drag = (id, from, to, steps = 10) => page.evaluate(({ id, from, to, steps }) => {
  const fire = (type, x, y) => window.dispatchEvent(new PointerEvent(type, {
    pointerId: id, pointerType: 'touch', clientX: x, clientY: y, bubbles: true, cancelable: true, isPrimary: id === 1
  }))
  fire('pointerdown', from.x, from.y)
  for (let i = 1; i <= steps; i++) fire('pointermove', from.x + (to.x - from.x) * i / steps, from.y + (to.y - from.y) * i / steps)
  fire('pointerup', to.x, to.y)
}, { id, from, to, steps })
const toast = () => page.evaluate(() => document.getElementById('toast').textContent.trim())
const keys = () => page.evaluate(() => ({ yaw: +window.__nightsDebug.state.cameraYaw.toFixed(3), pitch: +window.__nightsDebug.state.cameraPitch.toFixed(3) }))

try {
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(600)

  // ---------- Too far in a clean spot ----------
  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.player.position.set(0, d.getGroundHeight(0, 4), 4)
    d.state.cameraYaw = 0; d.state.cameraPitch = 0; d.state.cameraInitialized = false
    d.spawnGroundItem('wood', 0, 11, { startY: 0.6, pickupDelay: 0 })
  })
  await page.waitForTimeout(800)
  const far = await page.evaluate(() => {
    const d = window.__nightsDebug
    const item = d.groundItems[d.groundItems.length - 1]
    const v = item.mesh.getWorldPosition(item.mesh.position.clone()).project(d.camera)
    return { x: (v.x + 1) / 2 * innerWidth, y: (-v.y + 1) / 2 * innerHeight }
  })
  await tapAt(far.x, far.y, 61)
  await page.waitForTimeout(250)
  result.tooFar = await toast()

  // ---------- Iron rock (pickaxe) + outline ----------
  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.ownedTools.pickaxe = true
    d.equipTool('pickaxe')
    const rock = d.ironRocks.find(r => !r.broken)
    const yaw = Math.atan2(rock.x - 0, rock.z - 1.5)
    d.player.position.set(rock.x - Math.sin(yaw) * 2.1, d.getGroundHeight(rock.x, rock.z), rock.z - Math.cos(yaw) * 2.1)
    d.state.cameraYaw = yaw; d.state.cameraPitch = 0; d.state.cameraInitialized = false
    d.state.interactCooldown = 0
    window.__rockIndex = d.ironRocks.indexOf(rock)
  })
  await page.waitForTimeout(800)
  const rockBefore = await page.evaluate((i) => ({ hits: window.__nightsDebug.ironRocks[i].hits, broken: window.__nightsDebug.ironRocks[i].broken }), await page.evaluate(() => window.__rockIndex))
  const rockScreen = await page.evaluate((i) => {
    const d = window.__nightsDebug
    const rock = d.ironRocks[i]
    const v = rock.group.getWorldPosition(rock.group.position.clone())
    v.y += 0.4
    v.project(d.camera)
    return { x: (v.x + 1) / 2 * innerWidth, y: (-v.y + 1) / 2 * innerHeight }
  }, await page.evaluate(() => window.__rockIndex))
  await tapAt(rockScreen.x, rockScreen.y, 62)
  result.outlineShells = await page.evaluate(() => {
    let n = 0
    window.__nightsDebug.ironRocks.forEach(r => r.group.traverse(o => { if (o.userData.outlineShell) n++ }))
    return n
  })
  await page.waitForTimeout(350)
  const rockAfter = await page.evaluate((i) => ({ hits: window.__nightsDebug.ironRocks[i].hits, broken: window.__nightsDebug.ironRocks[i].broken, items: window.__nightsDebug.groundItems.filter(g => g.type === 'iron' && !g.carried).length }), await page.evaluate(() => window.__rockIndex))
  result.rockMine = { before: rockBefore, after: rockAfter, toast: await toast() }

  // ---------- Monster tap ----------
  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.ownedTools.ironSword = true
    d.equipTool('ironSword')
    const e = d.enemies[0]
    e.visible = true
    e.userData.dead = false
    e.userData.fading = false
    e.userData.health = 2
    e.position.set(0, d.getGroundHeight(0, 1.2), 1.2)
    d.player.position.set(0, d.getGroundHeight(0, 4), 4)
    d.state.cameraYaw = 0; d.state.cameraPitch = 0; d.state.cameraInitialized = false
    d.state.attackCooldown = 0
  })
  await page.waitForTimeout(700)
  const enemyScreen = await page.evaluate(() => {
    const d = window.__nightsDebug
    const v = d.enemies[0].position.clone(); v.y += 1.1
    v.project(d.camera)
    return { x: (v.x + 1) / 2 * innerWidth, y: (-v.y + 1) / 2 * innerHeight }
  })
  await tapAt(enemyScreen.x, enemyScreen.y, 63)
  await page.waitForTimeout(250)
  result.enemyTap = await page.evaluate(() => {
    const e = window.__nightsDebug.enemies[0]
    return { health: e.userData.health, hitTimer: +e.userData.hitTimer.toFixed(2), dead: !!e.userData.dead }
  })
  await shot('monster-tap')

  // ---------- Left-half drag does not rotate ----------
  const k0 = await keys()
  await drag(71, { x: 120, y: 180 }, { x: 300, y: 180 })
  await page.waitForTimeout(150)
  const k1 = await keys()
  result.leftDrag = { yawDelta: +(k1.yaw - k0.yaw).toFixed(4), pitchDelta: +(k1.pitch - k0.pitch).toFixed(4) }

  // ---------- Right-half drag rotates, left half does not interact ----------
  await drag(72, { x: 600, y: 180 }, { x: 760, y: 120 })
  await page.waitForTimeout(150)
  const k2 = await keys()
  result.rightDrag = { yawDelta: +(k2.yaw - k1.yaw).toFixed(4), pitchDelta: +(k2.pitch - k1.pitch).toFixed(4) }

  // ---------- Pitch clamp ----------
  await page.evaluate(() => { window.__nightsDebug.state.cameraPitch = 0 })
  for (let i = 0; i < 4; i++) await drag(80 + i, { x: 700, y: 370 }, { x: 700, y: 10 })
  await page.waitForTimeout(150)
  result.pitchMax = await page.evaluate(() => +window.__nightsDebug.state.cameraPitch.toFixed(3))
  for (let i = 0; i < 8; i++) await drag(90 + i, { x: 700, y: 10 }, { x: 700, y: 380 })
  await page.waitForTimeout(150)
  result.pitchMin = await page.evaluate(() => +window.__nightsDebug.state.cameraPitch.toFixed(3))
  result.pitchLimit = +(80 * Math.PI / 180).toFixed(3)

  // ---------- Third-person camera clears when obstruction ends ----------
  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.cameraPitch = 0
    d.player.position.set(0, d.getGroundHeight(0, 10), 10)
    d.state.cameraYaw = 0
    d.state.cameraInitialized = false
  })
  await page.waitForTimeout(800)
  result.openDistance = await page.evaluate(() => {
    const d = window.__nightsDebug
    const p = d.player.position.clone(); p.y += d.CAMERA_EYE_HEIGHT
    return +d.camera.position.distanceTo(p).toFixed(2)
  })
  await shot('third-person-open')

  result.errors = errors
} catch (e) {
  result.failure = String(e && e.stack || e)
  result.errors = errors
  try { await shot('failure') } catch {}
} finally {
  await browser.close()
}
console.log(JSON.stringify(result, null, 2))

