1562: function findNearestGroundItem(range, filter = null) {
1563:   let closest = range * range;
1564:   let found = null;
1565:   for (const item of groundItems) {
1566:     if (item.carried || item.popping > 0) continue;
1567:     if (filter && !filter(item)) continue;
1568:     const dx = player.position.x - item.x;
1569:     const dz = player.position.z - item.z;
1570:     const distanceSq = dx * dx + dz * dz;
1571:     if (distanceSq < closest) {
1572:       closest = distanceSq;
1573:       found = item;
1574:     }
1575:   }
1576:   return found;
1577: }
