2086: function updateMachine(delta) {
2087:   const job = machineState.working ? UPGRADES[machineState.working] : null;
2088:   const burning = !!job && machineState.fuel > 0 && !machineState.stalled;
2089: 
2090:   if (job && !machineState.stalled) {
2091:     if (machineState.fuel > 0) {
2092:       machineState.fuel = Math.max(0, machineState.fuel - delta * MACHINE_FUEL_DRAIN);
2093:       machineState.progress += delta;
2094:       machineState.clankTimer -= delta;
2095:       if (machineState.clankTimer <= 0) {
2096:         playMachineClank();
2097:         machineState.clankTimer = 0.42 + Math.random() * 0.38;
2098:       }
2099: 
2100:       if (machineState.fuel <= 0 && machineState.progress < job.time) {
2101:         machineState.stalled = true;
2102:         machineState.statusText = 'Out of fuel';
2103:         machineState.statusTimer = 3;
2104:         stopMachineSound();
2105:         showToast('Machine is out of fuel - add wood');
2106:       } else if (machineState.progress >= job.time) {
2107:         completeUpgrade();
2108:       }
2109:     }
2110:   }
2111: 
2112:   if (machineState.statusTimer > 0) {
2113:     machineState.statusTimer = Math.max(0, machineState.statusTimer - delta);
2114:   }
2115: 
2116:   const t = performance.now() * 0.001;
2117:   machinePanelMaterial.emissiveIntensity = burning
2118:     ? 1.15 + Math.sin(t * 11) * 0.25
2119:     : 0.62 + Math.sin(t * 2.2) * 0.1;
2120:   machineParts.glow.intensity = burning
2121:     ? 1.8 + Math.sin(t * 13) * 0.35
2122:     : 0.8 + Math.sin(t * 2.4) * 0.1;
2123: 
2124:   if (burning) {
2125:     machineState.gearAngle += delta * 2.6;
2126:     machineGears[0].rotation.x = machineState.gearAngle;
2127:     machineGears[1].rotation.x = -machineState.gearAngle * 0.7;
2128:   }
2129: 
2130:   for (let i = 0; i < machineSmokePuffs.length; i += 1) {
2131:     const puff = machineSmokePuffs[i];
