2189: function updateGroundItems(delta) {
2190:   const now = performance.now();
2191: 
2192:   for (let i = groundItems.length - 1; i >= 0; i -= 1) {
2193:     const item = groundItems[i];
2194: 
2195:     if (item.popping > 0) {
2196:       item.popping = Math.max(0, item.popping - delta);
2197:       const progress = 1 - item.popping / item.popDuration;
2198:       item.mesh.scale.setScalar(item.baseScale * (1 + progress * 1.1));
2199:       item.mesh.position.y += delta * 1.35;
2200:       if (item.popping <= 0) removeGroundItem(item);
2201:       continue;
2202:     }
2203: 
2204:     if (item.carried) {
2205:       const index = carriedItems.indexOf(item);
2206:       const spread = (index - (carriedItems.length - 1) / 2) * 0.62;
2207:       const angle = player.rotation.y + Math.PI + spread + Math.sin(now * 0.0012) * 0.05;
2208:       const distance = 0.95;
2209:       const targetX = player.position.x + Math.sin(angle) * distance;
2210:       const targetZ = player.position.z + Math.cos(angle) * distance;
2211:       const targetY = getGroundHeight(targetX, targetZ) + 0.52 + index * 0.06
2212:         + Math.sin(now * 0.003 + index) * 0.04;
2213:       const damping = 1 - Math.exp(-8 * delta);
2214:       item.mesh.position.x += (targetX - item.mesh.position.x) * damping;
2215:       item.mesh.position.y += (targetY - item.mesh.position.y) * damping;
2216:       item.mesh.position.z += (targetZ - item.mesh.position.z) * damping;
2217:       item.mesh.rotation.y += delta * 1.25;
2218:       continue;
2219:     }
2220: 
2221:     item.pickupDelay = Math.max(0, item.pickupDelay - delta);
2222: 
2223:     if (!item.landed) {
2224:       item.velocityY -= 13 * delta;
2225:       item.mesh.position.y += item.velocityY * delta;
2226:       if (item.type === 'wood') item.mesh.rotation.y += delta * 3.2;
2227:       if (item.type === 'sapling') item.mesh.rotation.y += delta * 2.4;
2228:       const restY = item.groundY + item.restY;
2229:       if (item.mesh.position.y <= restY) {
2230:         item.mesh.position.y = restY;
2231:         item.landed = true;
2232:       }
2233:     } else {
2234:       item.mesh.position.y = item.groundY + item.restY
2235:         + Math.abs(Math.sin(now * 0.0028 + item.mesh.id)) * (item.type === 'berry' ? 0.025 : 0.018);
2236:       if (item.type === 'sapling') item.mesh.rotation.y += delta * 0.4;
2237:       if (item.type === 'berry') item.mesh.rotation.y += delta * 0.35;
2238:     }
2239:   }
2240: }
