2298: function updatePlantedSaplings(delta) {
2299:   for (let i = plantedSaplings.length - 1; i >= 0; i -= 1) {
2300:     const sapling = plantedSaplings[i];
2301:     sapling.growth += delta;
2302:     const ratio = clamp(sapling.growth / SAPLING_GROW_TIME, 0, 1);
2303:     const scale = 0.35 + ratio * ratio * 0.95;
2304:     sapling.mesh.scale.setScalar(scale);
2305:     sapling.mesh.rotation.z = Math.sin(performance.now() * 0.0016 + sapling.sway) * 0.035;
2306: 
2307:     if (ratio >= 1) {
2308:       world.remove(sapling.mesh);
2309:       plantedSaplings.splice(i, 1);
2310:       const tree = createTree(sapling.x, sapling.z, 0.9 + Math.random() * 0.35);
2311:       tree.userData.planted = true;
