2317: function updateTrees(delta) {
2318:   const t = performance.now() * 0.001;
2319:   const damping = 1 - Math.exp(-10 * delta);
2320:   for (const tree of treeData) {
2321:     if (!tree.visible) continue;
2322:     const data = tree.userData;
2323: 
2324:     if (data.falling) {
2325:       data.fallProgress = Math.min(1, data.fallProgress + delta / TREE_FALL_TIME);
2326:       const angle = data.fallProgress * data.fallProgress * Math.PI * 0.5;
2327:       tree.quaternion.setFromAxisAngle(data.fallAxis, angle);
2328:       if (data.fallProgress >= 1 && !data.lootDropped) {
2329:         data.lootDropped = true;
2330:         playTreeCrash();
2331:         for (let i = 0; i < 3; i += 1) dropLog(tree, i);
2332:         dropSapling(tree);
2333:       }
2334:       if (data.fallProgress >= 1) tree.visible = false;
2335:       continue;
2336:     }
2337: 
2338:     if (!data.choppable) continue;
2339:     const highlighted = tree === state.targetTree ? 1 : 0;
2340:     data.highlight += (highlighted - data.highlight) * damping;
2341: 
2342:     const material = data.trunk.material;
2343:     material.emissiveIntensity = data.highlight * (0.45 + Math.sin(t * 7) * 0.16);
2344: 
2345:     if (data.shake > 0) {
2346:       data.shake = Math.max(0, data.shake - delta);
2347:       const strength = data.shake / TREE_SHAKE_TIME;
2348:       tree.rotation.z = Math.sin(t * 55) * 0.055 * strength;
2349:       tree.rotation.x = Math.cos(t * 43) * 0.03 * strength;
2350:     } else if (tree.rotation.z !== 0 || tree.rotation.x !== 0) {
2351:       tree.rotation.z = 0;
2352:       tree.rotation.x = 0;
2353:     }
2354:   }
2355: }
