3443: function handleWorldTap(clientX, clientY) {
3444:   if (interactionBlocked()) return;
3445:   const rect = canvas.getBoundingClientRect();
3446:   tapPointer.x = ((clientX - rect.left) / rect.width) * 2 - 1;
3447:   tapPointer.y = -((clientY - rect.top) / rect.height) * 2 + 1;
3448:   tapRaycaster.setFromCamera(tapPointer, camera);
3449: 
3450:   const candidates = [];
3451:   for (const item of groundItems) {
3452:     if (item.carried || item.popping > 0) continue;
3453:     candidates.push(item.mesh);
3454:   }
3455:   for (const rock of ironRocks) {
3456:     if (!rock.broken) candidates.push(rock.group);
3457:   }
3458:   for (const tree of treeData) {
3459:     if (tree.visible && tree.userData.choppable && !tree.userData.falling) candidates.push(tree);
3460:   }
3461:   for (const enemy of enemies) {
3462:     if (enemy.visible && !enemy.userData.fading && !enemy.userData.dead) candidates.push(enemy);
3463:   }
3464:   for (const sapling of plantedSaplings) candidates.push(sapling.mesh);
3465:   for (const bush of berryBushes) candidates.push(bush.mesh);
3466:   candidates.push(machine, campfire);
3467: 
3468:   if (candidates.length === 0) return;
3469: 
3470:   const hits = tapRaycaster.intersectObjects(candidates, true);
3471:   for (const hit of hits) {
3472:     // Particle systems (sparks, smoke) can intersect anywhere along the ray and
3473:     // would otherwise swallow taps aimed at the world behind them.
3474:     if (!hit.object.isMesh) continue;
3475:     const owner = resolveTapOwner(hit.object);
3476:     if (owner) {
3477:       applyTapInteraction(owner);
3478:       return;
3479:     }
3480:   }
3481: }
