3381: const tapRaycaster = new THREE.Raycaster();
3382: const tapPointer = new THREE.Vector2();
3383: 
3384: const OUTLINE_TIME = 0.3;
3385: const outlineMaterial = new THREE.MeshBasicMaterial({
3386:   color: 0xffffff,
3387:   side: THREE.BackSide,
3388:   transparent: true,
3389:   opacity: 0.9,
3390:   depthWrite: false
3391: });
3392: const outlineEffects = [];
3393: 
3394: function flashOutline(root) {
3395:   if (!root) return;
3396:   // Collect first: adding shells while traversing would recurse forever.
3397:   const targets = [];
3398:   root.traverse((node) => {
3399:     if (!node.isMesh || !node.geometry || node.userData.outlineShell) return;
3400:     targets.push(node);
3401:   });
3402:   if (targets.length === 0) return;
3403:   const shells = [];
3404:   for (const node of targets) {
3405:     const shell = new THREE.Mesh(node.geometry, outlineMaterial);
3406:     shell.scale.setScalar(1.05);
3407:     shell.renderOrder = 3;
3408:     shell.userData.outlineShell = true;
3409:     node.add(shell);
3410:     shells.push({ node, shell });
3411:   }
3412:   outlineEffects.push({ shells, until: performance.now() + OUTLINE_TIME * 1000 });
3413: }
3414: 
3415: function updateOutlines() {
3416:   if (outlineEffects.length === 0) return;
3417:   const now = performance.now();
3418:   for (let i = outlineEffects.length - 1; i >= 0; i -= 1) {
3419:     const effect = outlineEffects[i];
3420:     if (now < effect.until) continue;
3421:     for (const { node, shell } of effect.shells) node.remove(shell);
3422:     outlineEffects.splice(i, 1);
3423:   }
3424: }
3425: 
3426: function resolveTapOwner(object) {
3427:   let node = object;
3428:   while (node) {
3429:     const data = node.userData;
3430:     if (data.itemRef) return { kind: 'item', item: data.itemRef, mesh: node };
3431:     if (data.rockRef) return { kind: 'rock', rock: data.rockRef };
3432:     if (data.treeRef) return { kind: 'tree', tree: data.treeRef };
3433:     if (data.enemyRef) return { kind: 'enemy', enemy: data.enemyRef };
3434:     if (data.saplingRef) return { kind: 'sapling', sapling: data.saplingRef };
3435:     if (data.berryBushRef) return { kind: 'berry', bush: data.berryBushRef };
3436:     if (data.machineRef) return { kind: 'machine' };
3437:     if (data.campfireRef) return { kind: 'campfire' };
3438:     node = node.parent;
3439:   }
3440:   return null;
3441: }
