3643: function attack(targetEnemy = null) {
3644:   if (!state.started || state.gameOver || state.falling || state.paused || state.machineOpen || state.settingsOpen) return;
3645:   if (state.attackCooldown > 0) return;
3646:   const stats = TOOL_STATS[state.equippedTool];
3647:   if (!stats) {
3648:     showToast(state.equippedTool === 'backpack' ? 'Unequip the backpack to fight' : 'Equip a tool to attack');
3649:     return;
3650:   }
3651: 
3652:   if (targetEnemy) {
3653:     player.rotation.y = Math.atan2(
3654:       targetEnemy.position.x - player.position.x,
3655:       targetEnemy.position.z - player.position.z
3656:     );
3657:   } else if (state.firstPerson) {
3658:     // In first-person, strikes follow where the camera looks.
3659:     player.rotation.y = state.cameraYaw;
3660:   }
3661: 
3662:   state.attackCooldown = stats.cooldown;
3663:   state.attackTimer = ATTACK_DURATION;
3664:   strikeArc.visible = true;
3665:   strikeArc.scale.setScalar(0.7);
3666:   playerGlow.intensity = 1.8;
3667:   playAxeWhoosh();
3668: 
3669:   if (!targetEnemy) {
3670:     if (state.targetRock && stats.rockPower > 0) {
3671:       mineIronRock(state.targetRock, stats.rockPower);
3672:     } else if (state.targetTree && stats.treePower > 0) {
3673:       chopTree(state.targetTree, stats.treePower);
3674:     }
3675:   }
3676: 
3677:   const forward = new THREE.Vector3(Math.sin(player.rotation.y), 0, Math.cos(player.rotation.y));
3678: 
3679:   if (targetEnemy) {
3680:     if (targetEnemy.visible && !targetEnemy.userData.fading) {
3681:       const offset = targetEnemy.position.clone().sub(player.position);
3682:       offset.y = 0;
3683:       if (offset.length() <= TAP_REACH) damageEnemy(targetEnemy, stats, forward);
3684:     }
3685:     return;
3686:   }
3687: 
3688:   for (const enemy of enemies) {
3689:     if (!enemy.visible || enemy.userData.fading) continue;
3690:     const offset = enemy.position.clone().sub(player.position);
3691:     offset.y = 0;
3692:     const distance = offset.length();
3693:     if (distance > stats.range || distance < 0.01) continue;
3694:     offset.normalize();
3695:     if (forward.dot(offset) < 0.2) continue;
3696:     damageEnemy(enemy, stats, forward);
3697:   }
3698: }
