3703:   data.hitTimer = 0.22;
3704:   data.bodyMat.emissive.setHex(0xff2f1a);
3705:   data.bodyMat.emissiveIntensity = 1.1;
3706:   data.knockback.addScaledVector(forward, 4.2 + stats.damage * 0.6);
3707:   playMeleeHit();
3708: 
3709:   hitEffect.position.copy(enemy.position);
3710:   hitEffect.position.y += 1.15;
3711:   hitEffect.scale.setScalar(0.8);
3712:   hitEffect.material.opacity = 0.95;
3713:   hitEffect.visible = true;
3714:   state.hitEffectTimer = 0.22;
3715: 
3716:   if (data.health <= 0) {
3717:     data.health = 0;
3718:     data.dead = true;
3719:     data.attackCooldown = 0;
3720:     startEnemyFade(enemy, 4);
3721:   }
3722: }
