4000:     const swing = Math.sin(clamp(progress, 0, 1) * Math.PI);
4001:     leftArmX = 0.22 * swing;
4002:     rightArmX = -0.45 - 2.25 * swing;
4003:     rightArmZ = 0.34 * swing;
4004:     leftLegX = 0.08 * swing;
4005:     rightLegX = -0.08 * swing;
4006:   } else if (state.chopTimer > 0) {
4007:     const progress = 1 - state.chopTimer / 0.3;
4008:     const swing = Math.sin(clamp(progress, 0, 1) * Math.PI);
4009:     leftArmX = -0.4 * swing;
4010:     rightArmX = -2.2 * swing;
4011:     rightArmZ = 0.12 * swing;
4012:   } else if (state.equipTimer > 0) {
4013:     const progress = 1 - state.equipTimer / EQUIP_TIME;
4014:     const lift = Math.sin(clamp(progress, 0, 1) * Math.PI);
4015:     rightArmX = -1.15 * lift;
4016:     rightArmZ = 0.22 * lift;
4017:     leftArmX = 0.18 * lift;
4018:   } else if (state.moveSpeed > 0.1) {
4019:     state.walkPhase += delta * (5 + state.moveSpeed);
4020:     const swing = Math.sin(state.walkPhase) * 0.72;
4021:     leftArmX = swing;
4022:     rightArmX = -swing;
4023:     leftLegX = -swing;
4024:     rightLegX = swing;
