4031:   const damping = 1 - Math.exp(-14 * delta);
4032:   leftArm.rotation.x += (leftArmX - leftArm.rotation.x) * damping;
4033:   rightArm.rotation.x += (rightArmX - rightArm.rotation.x) * damping;
4034:   leftArm.rotation.z += (leftArmZ - leftArm.rotation.z) * damping;
4035:   rightArm.rotation.z += (rightArmZ - rightArm.rotation.z) * damping;
4036:   leftLeg.rotation.x += (leftLegX - leftLeg.rotation.x) * damping;
4037:   rightLeg.rotation.x += (rightLegX - rightLeg.rotation.x) * damping;
