4083: 
4084:     const playerDistance = Math.hypot(
4085:       player.position.x - enemy.position.x,
4086:       player.position.z - enemy.position.z
4087:     );
4088: 
4089:     let targetX = player.position.x;
4090:     let targetZ = player.position.z;
