4095: 
4096:     let dx = targetX - enemy.position.x;
4097:     let dz = targetZ - enemy.position.z;
4098:     const targetDistance = Math.hypot(dx, dz);
4099:     let stepX = 0;
4100:     let stepZ = 0;
4101:     let walking = false;
