4146:     enemy.position.x = clamp(nextX, -46, 46);
4147:     enemy.position.z = clamp(nextZ, -46, 46);
4148:     resolveWorldPropCollisions(enemy, 0.36);
4149:     enemy.position.x = clamp(enemy.position.x, -46, 46);
