4304: function updateDayNight(delta) {
4305:   const previousTime = state.cycleTime;
4306:   state.cycleTime += delta;
4307:   let wrapped = false;
4308:   if (state.cycleTime >= CYCLE_LENGTH) {
4309:     state.cycleTime -= CYCLE_LENGTH;
4310:     wrapped = true;
4311:   }
4312:   const t = state.cycleTime;
4313: 
4314:   if (t < DAY_LENGTH - DUSK_LENGTH) {
4315:     state.daylight = 1;
4316:   } else if (t < DAY_LENGTH) {
4317:     state.daylight = 1 - smoothstep((t - (DAY_LENGTH - DUSK_LENGTH)) / DUSK_LENGTH);
4318:   } else if (t < CYCLE_LENGTH - DAWN_LENGTH) {
4319:     state.daylight = 0;
4320:   } else {
4321:     state.daylight = smoothstep((t - (CYCLE_LENGTH - DAWN_LENGTH)) / DAWN_LENGTH);
4322:   }
4323: 
4324:   if (previousTime < DAY_LENGTH && t >= DAY_LENGTH && !state.nightActive) {
4325:     spawnNightWave();
4326:   }
4327: 
4328:   if (previousTime < CYCLE_LENGTH - DAWN_LENGTH && t >= CYCLE_LENGTH - DAWN_LENGTH) {
4329:     for (const enemy of enemies) {
4330:       if (enemy.visible && !enemy.userData.fading && !enemy.userData.dead) {
4331:         startEnemyFade(enemy, 0.3);
