3920: function checkAutoJump(nextX, nextZ, moveDir) {
3921:   if (!state.grounded) return;
3922:   for (const obstacle of lowObstacles) {
3923:     if (obstacle.rock && obstacle.rock.broken) continue;
3924:     const dx = nextX - obstacle.x;
3925:     const dz = nextZ - obstacle.z;
3926:     const reach = obstacle.radius + PLAYER_RADIUS + 0.12;
3927:     if (dx * dx + dz * dz > reach * reach) continue;
3928:     const towardX = obstacle.x - nextX;
3929:     const towardZ = obstacle.z - nextZ;
3930:     if (moveDir.x * towardX + moveDir.z * towardZ <= 0) continue;
3931:     if (obstacle.top - player.position.y <= 0.95) {
3932:       tryJump();
3933:       return;
3934:     }
3935:   }
3936: }
