3938: function movePlayer(delta) {
3939:   if (!state.started || state.gameOver || state.falling) return;
3940:   const keys = state.keys;
3941:   const keyX = (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0);
3942:   const keyY = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
3943:   const moveX = clamp(state.joystick.x + keyX, -1, 1);
3944:   const moveY = clamp(-state.joystick.y + keyY, -1, 1);
3945:   if (Math.abs(moveX) + Math.abs(moveY) < 0.02) {
3946:     state.moveSpeed = 0;
3947:     return;
3948:   }
3949: 
3950:   const forward = new THREE.Vector3(Math.sin(state.cameraYaw), 0, Math.cos(state.cameraYaw));
3951:   const right = new THREE.Vector3(-Math.cos(state.cameraYaw), 0, Math.sin(state.cameraYaw));
3952:   const moveDir = new THREE.Vector3();
3953:   moveDir.addScaledVector(forward, moveY);
3954:   moveDir.addScaledVector(right, moveX);
3955:   moveDir.normalize();
3956: 
3957:   state.moveSpeed = PLAYER_SPEED;
3958:   const targetYaw = Math.atan2(moveDir.x, moveDir.z);
3959:   const turn = 1 - Math.exp(-15 * delta);
3960:   player.rotation.y = lerpAngle(player.rotation.y, targetYaw, turn);
3961: 
3962:   const nextX = player.position.x + moveDir.x * delta * PLAYER_SPEED;
3963:   const nextZ = player.position.z + moveDir.z * delta * PLAYER_SPEED;
3964:   checkAutoJump(nextX, nextZ, moveDir);
3965: 
3966:   player.position.x = nextX;
3967:   player.position.z = nextZ;
3968:   resolveTreeCollisions();
3969:   resolveWorldPropCollisions(player);
3970:   player.position.x = clamp(player.position.x, -30, 30);
3971:   player.position.z = clamp(player.position.z, -30, 30);
