3483: function applyTapInteraction(owner) {
3484:   const px = player.position.x;
3485:   const pz = player.position.z;
3486:   const withinReach = (x, z) => Math.hypot(px - x, pz - z) <= TAP_REACH;
3487:   const tooFar = () => showToast('Too far');
3488: 
3489:   switch (owner.kind) {
3490:     case 'item': {
3491:       const item = owner.item;
3492:       if (!withinReach(item.x, item.z)) return tooFar();
3493:       flashOutline(item.mesh);
3494:       pickUpItem(item);
3495:       return;
3496:     }
3497:     case 'rock': {
3498:       const rock = owner.rock;
3499:       if (!withinReach(rock.x, rock.z)) return tooFar();
3500:       flashOutline(rock.group);
3501:       if (!canMineTool(state.equippedTool)) {
3502:         showToast('Equip the pickaxe to mine iron');
3503:         return;
3504:       }
3505:       mineIronRock(rock);
3506:       return;
3507:     }
3508:     case 'tree': {
3509:       const tree = owner.tree;
3510:       if (!withinReach(tree.position.x, tree.position.z)) return tooFar();
3511:       flashOutline(tree);
3512:       if (!canChopTool(state.equippedTool)) {
3513:         showToast('Equip the axe to chop');
3514:         return;
3515:       }
3516:       chopTree(tree, TOOL_STATS[state.equippedTool]?.treePower ?? 1);
3517:       return;
3518:     }
3519:     case 'enemy': {
3520:       const enemy = owner.enemy;
3521:       if (!withinReach(enemy.position.x, enemy.position.z)) return tooFar();
3522:       flashOutline(enemy);
3523:       attack(enemy);
3524:       return;
3525:     }
3526:     case 'sapling': {
3527:       if (!withinReach(owner.sapling.x, owner.sapling.z)) return tooFar();
3528:       flashOutline(owner.sapling.mesh);
3529:       showToast('The sapling is still growing');
3530:       return;
3531:     }
3532:     case 'berry': {
3533:       const bush = owner.bush;
3534:       if (!withinReach(bush.x, bush.z)) return tooFar();
3535:       flashOutline(bush.mesh);
3536:       harvestBerryBush(bush);
3537:       return;
3538:     }
3539:     case 'machine': {
3540:       if (getMachineDistance() > TAP_REACH) return tooFar();
3541:       if (getMachineDistance() > MACHINE_INTERACT_RANGE) {
3542:         showToast('Move closer to the machine');
3543:         return;
3544:       }
3545:       flashOutline(machine);
3546:       openMachinePanel();
3547:       return;
3548:     }
3549:     case 'campfire': {
3550:       if (getCampfireDistance() > TAP_REACH) return tooFar();
3551:       flashOutline(campfire);
3552:       tapCampfire();
3553:       return;
3554:     }
3555:     default:
3556:       break;
3557:   }
3558: }
