3862: function resolveTreeCollisions() {
3863:   for (const tree of treeData) {
3864:     if (!tree.visible || tree.userData.falling) continue;
3865:     const dx = player.position.x - tree.position.x;
3866:     const dz = player.position.z - tree.position.z;
3867:     const radius = tree.userData.scale * 0.3 + PLAYER_RADIUS;
3868:     const distanceSq = dx * dx + dz * dz;
3869:     if (distanceSq >= radius * radius || distanceSq < 0.0001) continue;
3870:     const distance = Math.sqrt(distanceSq);
3871:     const push = radius - distance;
3872:     player.position.x += (dx / distance) * push;
3873:     player.position.z += (dz / distance) * push;
3874:   }
3875: }
3876: 
3877: function resolveWorldPropCollisions(entity, entityRadius = PLAYER_RADIUS) {
3878:   for (const prop of solidProps) {
3879:     if (prop.rock && prop.rock.broken) continue;
3880:     const dx = entity.position.x - prop.x;
3881:     const dz = entity.position.z - prop.z;
3882:     const radius = prop.radius + entityRadius;
3883:     const distanceSq = dx * dx + dz * dz;
3884:     if (distanceSq >= radius * radius) continue;
3885:     if (distanceSq < 0.0001) {
3886:       // Exactly on the prop: pick a deterministic direction to escape.
3887:       entity.position.x = prop.x + radius;
3888:       continue;
3889:     }
3890:     const distance = Math.sqrt(distanceSq);
3891:     const push = radius - distance;
3892:     entity.position.x += (dx / distance) * push;
3893:     entity.position.z += (dz / distance) * push;
3894:   }
3895: 
3896:   for (const wall of placedWalls) {
3897:     const dx = entity.position.x - wall.x;
3898:     const dz = entity.position.z - wall.z;
3899:     const cos = Math.cos(wall.rotation);
3900:     const sin = Math.sin(wall.rotation);
3901:     let localX = dx * cos - dz * sin;
3902:     let localZ = dx * sin + dz * cos;
3903:     const halfWidth = wall.width / 2 + entityRadius;
3904:     const halfDepth = wall.depth / 2 + entityRadius;
3905:     if (Math.abs(localX) >= halfWidth || Math.abs(localZ) >= halfDepth) continue;
3906: 
3907:     const pushX = halfWidth - Math.abs(localX);
3908:     const pushZ = halfDepth - Math.abs(localZ);
3909:     if (pushX < pushZ) {
3910:       localX = Math.sign(localX || 1) * halfWidth;
3911:     } else {
3912:       localZ = Math.sign(localZ || 1) * halfDepth;
3913:     }
3914: 
3915:     entity.position.x = wall.x + localX * cos + localZ * sin;
3916:     entity.position.z = wall.z - localX * sin + localZ * cos;
3917:   }
3918: }
