4134:       const nextOutX = nextX - campfire.position.x;
4135:       const nextOutZ = nextZ - campfire.position.z;
4136:       const nextOutDistance = Math.hypot(nextOutX, nextOutZ) || 1;
4137:       if (nextOutDistance < getFireScareRadius()) {
4138:         const keepX = enemy.position.x - campfire.position.x;
4139:         const keepZ = enemy.position.z - campfire.position.z;
4140:         const keepDistance = Math.hypot(keepX, keepZ) || 1;
