4213: 
4214:   spawnBurst.visible = spawnBurst.visible && spawnBurst.intensity > 0.1;
4215:   if (spawnBurst.visible) {
4216:     spawnBurst.intensity *= 0.96;
4217:   }
4218: 
4219:   const t = performance.now() * 0.001;
4220:   const flicker = 0.85 + Math.sin(t * 17.3) * 0.12 + Math.sin(t * 29.7 + 0.7) * 0.08;
4221:   const burning = !state.fireOut;
