4239: 
4240:     const innerHeight = 1.05 * size;
4241:     fireFlameInner.scale.setScalar(size * (0.92 + Math.sin(t * 14) * 0.1));
4242:     fireFlameInner.position.y = 0.42 + innerHeight * 0.5 + Math.sin(t * 10 + 1) * 0.03;
4243:     fireFlameInner.rotation.z = Math.sin(t * 4.7 + 1) * 0.07;
