4254: 
4255:   for (let i = 0; i < smokePuffs.length; i += 1) {
4256:     const puff = smokePuffs[i];
4257:     const phase = (t * 0.42 + i / smokePuffs.length) % 1;
4258:     puff.position.set(Math.sin(t * 1.4 + i) * 0.14, 1.5 + phase * 1.8, Math.cos(t * 1.2 + i) * 0.12);
