4512: function makeNoiseBuffer(ctx) {
4513:   const length = Math.floor(ctx.sampleRate * 2);
4514:   const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
4515:   const data = buffer.getChannelData(0);
4516:   let last = 0;
4517:   for (let i = 0; i < length; i += 1) {
4518:     const white = Math.random() * 2 - 1;
4519:     last = last * 0.72 + white * 0.28;
4520:     data[i] = last * 1.15;
4521:   }
4522:   return buffer;
4523: }
