4045: function updateEnemies(delta) {
4046:   if (!state.started || state.gameOver) return;
4047: 
4048:   const fireStrong = !state.fireOut && state.fuel > FIRE_STRONG_FUEL;
4049: 
4050:   for (const enemy of enemies) {
4051:     const data = enemy.userData;
4052:     if (!enemy.visible) continue;
4053: 
4054:     if (data.fading) {
4055:       data.fade = Math.max(0, data.fade - delta * (data.fadeRate || 1));
4056:       const fade = data.fade;
4057:       data.bodyMat.opacity = fade;
4058:       data.eyeMat.opacity = fade;
4059:       enemy.scale.setScalar(0.4 + fade * 0.6);
4060:       if (fade <= 0) {
4061:         enemy.visible = false;
4062:         data.fading = false;
4063:         data.dead = true;
4064:         enemy.position.set(0, -40, 0);
4065:       }
4066:       continue;
4067:     }
4068: 
4069:     if (state.falling > 0) continue;
4070: 
4071:     if (data.hitTimer > 0) {
4072:       data.hitTimer -= delta;
4073:       if (data.hitTimer <= 0) {
4074:         data.bodyMat.emissive.setHex(0x000000);
4075:         data.bodyMat.emissiveIntensity = 1;
4076:       }
4077:     }
4078: 
4079:     if (data.knockback.lengthSq() > 0.0004) {
4080:       enemy.position.addScaledVector(data.knockback, delta);
4081:       data.knockback.multiplyScalar(Math.exp(-9 * delta));
4082:     }
4083: 
4084:     const playerDistance = Math.hypot(
4085:       player.position.x - enemy.position.x,
4086:       player.position.z - enemy.position.z
4087:     );
4088: 
4089:     let targetX = player.position.x;
4090:     let targetZ = player.position.z;
4091:     if (data.targetCamp && playerDistance > 10 && !state.fireOut) {
4092:       targetX = campfire.position.x;
4093:       targetZ = campfire.position.z;
4094:     }
4095: 
4096:     let dx = targetX - enemy.position.x;
4097:     let dz = targetZ - enemy.position.z;
4098:     const targetDistance = Math.hypot(dx, dz);
4099:     let stepX = 0;
4100:     let stepZ = 0;
4101:     let walking = false;
4102: 
4103:     if (targetDistance > 0.35) {
4104:       stepX = (dx / targetDistance) * data.speed * delta;
4105:       stepZ = (dz / targetDistance) * data.speed * delta;
4106:       walking = true;
4107:     }
4108: 
4109:     if (fireStrong) {
4110:       const fx = enemy.position.x - campfire.position.x;
4111:       const fz = enemy.position.z - campfire.position.z;
4112:       const fireDistance = Math.hypot(fx, fz) || 1;
4113:       const nx = fx / fireDistance;
4114:       const nz = fz / fireDistance;
4115: 
4116:       if (fireDistance < getFireScareRadius() + 1.2) {
4117:         stepX += -nz * data.circleDir * data.speed * delta * 0.5;
4118:         stepZ += nx * data.circleDir * data.speed * delta * 0.5;
4119:       }
4120:     }
4121: 
4122:     let nextX = enemy.position.x + stepX;
4123:     let nextZ = enemy.position.z + stepZ;
4124: 
4125:     if (fireStrong) {
4126:       const outX = enemy.position.x - campfire.position.x;
4127:       const outZ = enemy.position.z - campfire.position.z;
4128:       const outDistance = Math.hypot(outX, outZ) || 1;
4129:       if (outDistance < getFireScareRadius() - 0.05) {
4130:         nextX = campfire.position.x + (outX / outDistance) * getFireScareRadius();
4131:         nextZ = campfire.position.z + (outZ / outDistance) * getFireScareRadius();
4132:       }
4133: 
4134:       const nextOutX = nextX - campfire.position.x;
4135:       const nextOutZ = nextZ - campfire.position.z;
4136:       const nextOutDistance = Math.hypot(nextOutX, nextOutZ) || 1;
4137:       if (nextOutDistance < getFireScareRadius()) {
4138:         const keepX = enemy.position.x - campfire.position.x;
4139:         const keepZ = enemy.position.z - campfire.position.z;
4140:         const keepDistance = Math.hypot(keepX, keepZ) || 1;
4141:         nextX = campfire.position.x + (keepX / keepDistance) * getFireScareRadius();
4142:         nextZ = campfire.position.z + (keepZ / keepDistance) * getFireScareRadius();
4143:       }
4144:     }
4145: 
4146:     enemy.position.x = clamp(nextX, -46, 46);
4147:     enemy.position.z = clamp(nextZ, -46, 46);
4148:     resolveWorldPropCollisions(enemy, 0.36);
