4159:     const stride = walking ? 0.58 : 0.1;
4160:     data.phase += delta * (3.4 + data.speed * 1.5) * (walking ? 1 : 0.3);
4161:     const swing = Math.sin(data.phase);
4162:     data.legs[0].rotation.x = swing * stride;
