4353: const cameraRaycaster = new THREE.Raycaster();
4354: const cameraPivot = new THREE.Vector3();
4355: const cameraForward = new THREE.Vector3();
4356: const thirdPersonPos = new THREE.Vector3();
4357: const firstPersonPos = new THREE.Vector3();
4358: const cameraDesired = new THREE.Vector3();
4359: const cameraLookTarget = new THREE.Vector3();
4360: const cameraLookForward = new THREE.Vector3();
4361: const cameraRayDirection = new THREE.Vector3();
4362: const cameraCandidates = [];
4363: 
4364: function updateCamera(delta = 0.016) {
4365:   const yaw = state.cameraYaw;
4366:   const pitch = state.cameraPitch;
4367:   const cosPitch = Math.cos(pitch);
4368:   const sinPitch = Math.sin(pitch);
4369: 
4370:   // Pivot sits at the character's eye height, so the camera rotates around the head.
4371:   cameraPivot.set(
4372:     player.position.x,
4373:     player.position.y + CAMERA_EYE_HEIGHT,
4374:     player.position.z
4375:   );
4376:   cameraForward.set(
4377:     Math.sin(yaw) * cosPitch,
4378:     sinPitch,
4379:     Math.cos(yaw) * cosPitch
4380:   );
4381: 
4382:   // Third-person: orbit the pivot from slightly above and behind.
4383:   const desiredDistance = state.cameraDistance || THIRD_PERSON_DISTANCE;
4384:   thirdPersonPos.copy(cameraPivot).addScaledVector(cameraForward, -desiredDistance);
4385:   thirdPersonPos.y += THIRD_CAMERA_HEIGHT;
4386: 
4387:   cameraRayDirection.copy(thirdPersonPos).sub(cameraPivot);
4388:   const fullDistance = cameraRayDirection.length();
4389:   if (fullDistance > 0.0001) cameraRayDirection.normalize();
4390: 
4391:   cameraCandidates.length = 0;
4392:   const broadRadius = desiredDistance + 3.2;
4393:   for (const tree of treeData) {
4394:     if (!tree.visible) continue;
4395:     const dx = tree.position.x - cameraPivot.x;
4396:     const dz = tree.position.z - cameraPivot.z;
4397:     if (dx * dx + dz * dz < broadRadius * broadRadius) {
4398:       cameraCandidates.push(tree.userData.cameraMeshes[0], tree.userData.cameraMeshes[1]);
4399:     }
4400:   }
4401:   for (const rock of ironRocks) {
4402:     if (rock.broken) continue;
4403:     if (Math.hypot(rock.x - cameraPivot.x, rock.z - cameraPivot.z) < broadRadius) {
4404:       cameraCandidates.push(rock.group);
4405:     }
4406:   }
4407:   for (const obstacle of lowObstacles) {
4408:     if (Math.hypot(obstacle.x - cameraPivot.x, obstacle.z - cameraPivot.z) < broadRadius) {
4409:       cameraCandidates.push(obstacle.mesh);
4410:     }
4411:   }
4412:   for (const wall of placedWalls) {
4413:     if (Math.hypot(wall.x - cameraPivot.x, wall.z - cameraPivot.z) < broadRadius) {
4414:       cameraCandidates.push(wall.group);
4415:     }
4416:   }
4417:   if (Math.hypot(machine.position.x - cameraPivot.x, machine.position.z - cameraPivot.z) < broadRadius) {
4418:     cameraCandidates.push(machine);
4419:   }
4420: 
4421:   let distance = fullDistance;
4422:   if (cameraCandidates.length > 0) {
4423:     cameraRaycaster.set(cameraPivot, cameraRayDirection);
4424:     cameraRaycaster.far = fullDistance;
4425:     const hits = cameraRaycaster.intersectObjects(cameraCandidates, true);
4426:     if (hits.length > 0) distance = Math.max(0.85, hits[0].distance - 0.24);
4427:   }
4428: 
4429:   thirdPersonPos.copy(cameraPivot).addScaledVector(cameraRayDirection, distance);
4430: 
4431:   // Never sink into the terrain.
4432:   const groundClearance = getGroundHeight(thirdPersonPos.x, thirdPersonPos.z) + 0.35;
4433:   if (thirdPersonPos.y < groundClearance) thirdPersonPos.y = groundClearance;
4434: 
4435:   firstPersonPos.copy(cameraPivot);
4436: 
4437:   // Ease between the two views.
4438:   const targetBlend = state.firstPerson ? 1 : 0;
4439:   const blendRate = 1 - Math.exp(-13 * delta);
4440:   state.viewBlend += (targetBlend - state.viewBlend) * blendRate;
4441:   if (Math.abs(state.viewBlend - targetBlend) < 0.0015) state.viewBlend = targetBlend;
4442:   const blend = smoothstep(clamp(state.viewBlend, 0, 1));
4443: 
4444:   cameraDesired.lerpVectors(thirdPersonPos, firstPersonPos, blend);
4445: 
4446:   const obstructed = distance < fullDistance - 0.01;
4447:   if (!state.cameraInitialized) {
4448:     camera.position.copy(cameraDesired);
4449:     state.cameraInitialized = true;
4450:   } else if (blend > 0.92) {
4451:     // Locked to the eye in first-person so movement never causes camera lag.
4452:     camera.position.copy(cameraDesired);
4453:   } else {
4454:     const follow = obstructed ? Math.min(1, blendRate * 3.4) : Math.min(1, blendRate * 0.95);
4455:     camera.position.lerp(cameraDesired, Math.max(0.12, follow));
4456:   }
4457:   const floor = getGroundHeight(camera.position.x, camera.position.z) + 0.28;
4458:   if (camera.position.y < floor) camera.position.y = floor;
4459: 
4460:   // Third-person looks at the head pivot; first-person looks straight ahead.
4461:   cameraLookTarget.copy(cameraPivot).lerp(
4462:     cameraLookForward.copy(cameraPivot).addScaledVector(cameraForward, 10),
4463:     blend
4464:   );
4465:   camera.lookAt(cameraLookTarget);
4466: 
4467:   const fov = THIRD_FOV + (FIRST_FOV - THIRD_FOV) * blend;
4468:   if (Math.abs(camera.fov - fov) > 0.01) {
4469:     camera.fov = fov;
4470:     camera.updateProjectionMatrix();
4471:   }
4472: 
4473:   const firstPersonActive = blend > 0.5;
4474:   avatar.visible = !firstPersonActive;
4475:   fpViewmodel.visible = firstPersonActive;
4476:   updateFpToolVisibility(firstPersonActive);
4477:   if (firstPersonActive) strikeArc.visible = false;
4478: }
