4588: function playTone(freq, endFreq, duration, type = 'sine', gain = 0.04, when = 0, attack = 0.008) {
4589:   if (!audioReady()) return;
4590:   const ctx = audio.ctx;
4591:   const start = audioNow() + Math.max(0, when);
4592:   const osc = ctx.createOscillator();
4593:   const env = ctx.createGain();
4594:   osc.type = type;
4595:   osc.frequency.setValueAtTime(Math.max(20, freq), start);
4596:   if (endFreq && endFreq !== freq) {
4597:     osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), start + duration);
4598:   }
4599:   env.gain.setValueAtTime(0.0001, start);
4600:   env.gain.linearRampToValueAtTime(gain, start + attack);
4601:   env.gain.exponentialRampToValueAtTime(0.0001, start + duration);
4602:   osc.connect(env).connect(audio.master);
4603:   osc.start(start);
4604:   osc.stop(start + duration + 0.04);
4605: }
