4607: function playNoise(duration, gain, filterType = 'lowpass', freq = 900, freqEnd = 0, Q = 0.8, when = 0) {
4608:   if (!audioReady()) return;
4609:   const ctx = audio.ctx;
4610:   const start = audioNow() + Math.max(0, when);
4611:   const source = ctx.createBufferSource();
4612:   source.buffer = audio.noiseBuffer;
4613:   const filter = ctx.createBiquadFilter();
4614:   filter.type = filterType;
4615:   filter.frequency.setValueAtTime(Math.max(40, freq), start);
4616:   if (freqEnd) filter.frequency.exponentialRampToValueAtTime(Math.max(40, freqEnd), start + duration);
4617:   filter.Q.value = Q;
4618:   const env = ctx.createGain();
4619:   env.gain.setValueAtTime(0.0001, start);
4620:   env.gain.linearRampToValueAtTime(gain, start + 0.006);
4621:   env.gain.exponentialRampToValueAtTime(0.0001, start + duration);
4622:   source.connect(filter).connect(env).connect(audio.master);
4623:   source.start(start, Math.random() * 1.2, duration + 0.04);
4624: }
