179: function createTree(x, z, scale = 1) {
180:   const tree = new THREE.Group();
181: 
182:   const trunk = new THREE.Mesh(
183:     new THREE.CylinderGeometry(0.18 * scale, 0.28 * scale, 1.7 * scale, 6),
184:     trunkMat
185:   );
186:   trunk.position.y = 0.85 * scale;
187:   trunk.castShadow = true;
188:   trunk.receiveShadow = true;
189:   tree.add(trunk);
190: 
191:   const foliage = new THREE.Mesh(
192:     new THREE.ConeGeometry(0.8 * scale, 2.2 * scale, 6),
193:     foliageMat
194:   );
195:   foliage.position.y = 2.4 * scale;
196:   foliage.castShadow = true;
197:   foliage.receiveShadow = true;
198:   tree.add(foliage);
199: 
200:   tree.position.set(x, getGroundHeight(x, z), z);
201:   tree.userData.scale = scale;
202:   tree.userData.cameraMeshes = [trunk, foliage];
203:   tree.userData.trunk = trunk;
204:   tree.userData.foliage = foliage;
205:   tree.userData.treeRef = tree;
206:   world.add(tree);
207:   treeData.push(tree);
208:   return tree;
209: }
