96: // Gentle rolling ground keeps the campfire clearing flat while giving the player
97: // broad, easy-to-climb slopes farther out in the forest.
98: function getGroundHeight(x, z) {
99:   const radius = Math.hypot(x, z);
100:   const inner = Math.min(Math.max((radius - 8) / 10, 0), 1);
101:   const outer = Math.min(Math.max((62 - radius) / 8, 0), 1);
102:   const waves = Math.sin(x * 0.11 + 0.7) * Math.cos(z * 0.1 - 0.35) * 0.55
103:     + Math.sin((x + z) * 0.055 - 0.6) * 0.35;
104:   return waves * inner * outer;
105: }
