175: function createTree(x, z, scale = 1) {
176:   const tree = new THREE.Group();
177: 
178:   const trunk = new THREE.Mesh(
179:     new THREE.CylinderGeometry(0.18 * scale, 0.28 * scale, 1.7 * scale, 6),
180:     trunkMat
181:   );
182:   trunk.position.y = 0.85 * scale;
183:   trunk.castShadow = true;
184:   trunk.receiveShadow = true;
185:   tree.add(trunk);
186: 
187:   const foliage = new THREE.Mesh(
188:     new THREE.ConeGeometry(0.8 * scale, 2.2 * scale, 6),
189:     foliageMat
190:   );
191:   foliage.position.y = 2.4 * scale;
192:   foliage.castShadow = true;
193:   foliage.receiveShadow = true;
194:   tree.add(foliage);
195: 
196:   tree.position.set(x, getGroundHeight(x, z), z);
197:   tree.userData.scale = scale;
198:   tree.userData.cameraMeshes = [trunk, foliage];
199:   tree.userData.trunk = trunk;
200:   tree.userData.foliage = foliage;
201:   tree.userData.treeRef = tree;
202:   world.add(tree);
203:   treeData.push(tree);
204:   return tree;
205: }
