1230:     const dx = player.position.x - tree.position.x;
1231:     const dz = player.position.z - tree.position.z;
1232:     const distanceSq = dx * dx + dz * dz;
1233:     if (distanceSq < closest) {
1234:       closest = distanceSq;
1235:       state.targetTree = tree;
1236:     }
1237:   }
1238: 
