1366:     : type === 'berry'
1367:       ? 0.14
1368:       : type === 'iron'
1369:         ? 0.13
1370:         : isHeldUpgrade
1371:           ? 0.5
1372:           : 0.02;
1373:   const baseScale = type === 'sapling' ? 0.72 : 1;
1374:   const startY = options.startY ?? (groundY + restY + 0.45);
1375: 
