1385:     restY,
1386:     baseScale,
1387:     velocityY: options.velocityY ?? (type === 'wood' ? 2.2 : 2.6),
1388:     landed: false,
1389:     pickupDelay: options.pickupDelay ?? 0.35,
1390:     carried: false,
1391:     popping: 0,
