      updatePlayerVertical(delta);
      updateEnemies(delta);
      updateVitals(delta);
      updateInteractionTarget();
      updateTrees(delta);
      updateGroundItems(delta);
      updatePlantedSaplings(delta);
      updateCampfire(delta);
      updateMachine(delta);
      updateIronRocks(delta);
