    const x = clusterX + Math.cos(angle) * radius;
    const z = clusterZ + Math.sin(angle) * radius;
    const scale = 0.88 + Math.random() * 0.38;
    if (!findRockSpot(x, z, scale)) continue;
    createIronRock(x, z, scale);
    placed += 1;
  }
}

