      g.fillRect(18, 44, 52, 26);
      g.fillStyle = '#b87a3d';
      g.beginPath();
      g.arc(18, 57, 13, 0, Math.PI * 2);
      g.fill();
      g.strokeStyle = '#8a5526';
      g.lineWidth = 3;
