  paint(value);
  const texture = new THREE.CanvasTexture(canvasEl);
  texture.colorSpace = THREE.SRGBColorSpace;
  return {
    mesh: null,
    setValue(amount, bright) {
      paint(amount);
      texture.needsUpdate = true;
      if (this.mesh) {
        this.mesh.scale.setScalar(1.2);
        this.pop = 1;
