/* ---------- Camera view toggle ---------- */

.camera-btn.first-person {
  color: #ffcf76;
  border-color: rgba(255, 207, 118, 0.55);
  background: rgba(38, 26, 8, 0.82);
  box-shadow: 0 0 14px rgba(255, 169, 67, 0.26), inset 0 1px rgba(255, 255, 255, 0.1);
}

/* Pointer input is handled globally so taps and camera drags can share the
   whole game surface without the look layer stealing interactions. */
#lookZone {
  pointer-events: none;
}

/* First-person viewmodel arm + tool are rendered by the camera itself. */

/* ---------- Leveling campfire HUD ---------- */

.fire-counter {
  position: fixed;
  left: 0;
  top: 0;
  z-index: 25;
  width: 188px;
  opacity: 0;
  pointer-events: none;
  text-align: center;
  transform: translate(-50%, -100%);
  transition: opacity 0.2s ease;
}

.fire-counter.visible {
  opacity: 1;
}

#fireCounterText {
  display: block;
  margin-bottom: 4px;
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  white-space: nowrap;
  text-shadow: 0 1px 2px #000, 0 0 4px #000, 1px 0 #000, -1px 0 #000, 0 1px #000, 0 -1px #000;
}

.fire-counter-track {
  height: 13px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.38);
  border-radius: 4px;
  background: #050808;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.65);
}

.fire-counter-fill {
  width: 50%;
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(90deg, #3fbf73, #78e39a);
  box-shadow: 0 0 10px rgba(95, 232, 139, 0.5);
  transition: width 0.2s linear, background 0.3s ease;
}

#startHint {
  position: fixed;
  left: 50%;
  top: max(70px, calc(env(safe-area-inset-top) + 62px));
  z-index: 31;
  max-width: calc(100vw - 28px);
  padding: 7px 14px;
  border: 1px solid rgba(255, 201, 112, 0.4);
  border-radius: 999px;
  background: rgba(5, 13, 17, 0.86);
  color: #ffe0a6;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -8px);
  transition: opacity 0.25s ease, transform 0.25s ease;
}

#startHint.visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

#fireFlash {
  position: fixed;
  inset: 0;
  z-index: 24;
  background: radial-gradient(circle at 50% 58%, rgba(255, 236, 190, 0.9), rgba(255, 149, 54, 0.4) 38%, transparent 72%);
  opacity: 0;
  pointer-events: none;
}

#fireFlash.flash {
  animation: fireLevelFlash 0.7s ease-out;
}

@keyframes fireLevelFlash {
  0% { opacity: 0; }
  18% { opacity: 0.82; }
  100% { opacity: 0; }
}

/* ---------- Bench prompt ---------- */

.bench-prompt {
  position: fixed;
  left: 0;
  top: 0;
  z-index: 25;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 6px 12px;
  border: 1px solid rgba(255, 209, 126, 0.55);
  border-radius: 12px;
  background: rgba(8, 16, 20, 0.88);
  color: #ffe3ae;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  pointer-events: none;
  transform: translate(-50%, -100%);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.45);
}

.bench-prompt.hidden {
  display: none;
}

.bench-hand {
  font-size: 17px;
  line-height: 1;
}

/* ---------- Place button ---------- */

#placeBtn {
  right: 4px;
  bottom: 96px;
  width: 64px;
  height: 64px;
  border-color: rgba(255, 196, 112, 0.55);
  background: radial-gradient(circle at 34% 28%, rgba(164, 112, 51, 0.64), rgba(37, 24, 11, 0.75));
  box-shadow: 0 0 18px rgba(255, 177, 73, 0.2), inset 0 1px rgba(255, 255, 255, 0.18);
}

/* ---------- Hotbar labels and extra slot ---------- */

.hotbar-slot {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 1px;
  height: 62px;
  padding: 5px 4px 3px;
}

.hotbar-slot svg {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
}

.hotbar-label {
  display: block;
  width: 100%;
  overflow: hidden;
  color: rgba(238, 247, 249, 0.7);
  font-size: 6px;
  font-weight: 700;
  letter-spacing: 0.03em;
  line-height: 1.1;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hotbar-slot.equipped .hotbar-label {
  color: #fff4d8;
}

/* ---------- Crafting bench panel ---------- */

.craft-panel {
  position: fixed;
  left: 50%;
  top: 50%;
  z-index: 36;
  display: flex;
  flex-direction: column;
