import { setTimeout as delay } from 'node:timers/promises';
import { spawn } from 'node:child_process';

const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
  '--window-size=1280,720', '--remote-debugging-port=9223',
  '--user-data-dir=/tmp/opencode/nights-cdp-profile', '--app=http://127.0.0.1:5173/'
], { stdio: 'ignore' });
let socket;
try {
  let targets;
  for (let i = 0; i < 80; i++) {
    try {
      targets = await (await fetch('http://127.0.0.1:9223/json')).json();
      if (targets.some((target) => target.type === 'page')) break;
    } catch {}
    await delay(250);
  }
  const page = targets?.find((target) => target.type === 'page');
  if (!page) throw new Error('Chromium page target did not start');
  socket = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    socket.addEventListener('open', resolve, { once: true });
    socket.addEventListener('error', reject, { once: true });
  });
  let id = 0;
  const pending = new Map();
  const exceptions = [];
  socket.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.method === 'Runtime.exceptionThrown') exceptions.push(msg.params.exceptionDetails.text);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  });
  const send = (method, params = {}) => new Promise((resolve) => {
    const commandId = ++id;
    pending.set(commandId, resolve);
    socket.send(JSON.stringify({ id: commandId, method, params }));
  });
  await send('Runtime.enable');
  await delay(1800);
  const result = await send('Runtime.evaluate', {
    expression: `(() => {
      const d = window.__nightsDebug;
      if (!d) return { error: 'dev debug API missing', width: innerWidth, height: innerHeight };
      d.startGame();
      const groundItem = (type, x, z) => {
        const item = d.spawnGroundItem(type, x, z, { pickupDelay: 0 });
        item.landed = true;
        item.mesh.position.y = item.groundY + item.restY;
        return item;
      };
      d.player.position.set(6.5, d.player.position.y, 2.6);
      for (let i = 0; i < 5; i++) { const item = groundItem('wood', 6.5, 2.6); d.pickUpItem(item); d.putInGrinder(); }
      const woodStock = d.benchState.stock.wood;
      const ironItem = groundItem('iron', 6.5, 2.6); d.pickUpItem(ironItem); d.putInGrinder();
      d.openCraftPanel();
      const panelVisible = !document.getElementById('craftPanel').classList.contains('hidden');
      d.selectRecipe('pickaxe'); d.craftSelectedRecipe();
      const craftedPickaxe = d.state.ownedTools.pickaxe === true;
      const postCraftStock = { ...d.benchState.stock };
      d.closeCraftPanel();
      d.player.position.set(d.campfire.position.x, d.player.position.y, d.campfire.position.z);
      d.state.fireProgress = 50; d.state.fireLevel = 1; d.state.fireOut = false;
      for (let i = 0; i < 2; i++) { const item = groundItem('wood', d.player.position.x, d.player.position.z); d.pickUpItem(item); d.putLogInFire(); }
      const leveled = d.state.fireLevel === 2 && d.state.fireProgress === 50;
      d.state.fireProgress = 0.001; d.updateCampfire(10);
      return { panelVisible, woodStock, grinderStock: { wood: woodStock, iron: 1 }, craftedPickaxe, postCraftStock, leveled, fireLevel: d.state.fireLevel, fireOut: d.state.fireOut, safeRadius: d.state.fireOut ? 0 : 'active', exceptions: [] };
    })()` ,
    returnByValue: true
  });
  const value = result.result?.result?.value;
  if (value?.exceptions) value.exceptions = exceptions;
  console.log(JSON.stringify({ result: value ?? result, exceptions }, null, 2));
} finally {
  socket?.close();
