import { setTimeout as delay } from 'node:timers/promises';
import { spawn } from 'node:child_process';

const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
  '--window-size=1280,800', '--remote-debugging-port=9224',
  '--user-data-dir=/tmp/opencode/nights-cdp-profile-2', '--app=http://127.0.0.1:5173/'
], { stdio: 'ignore' });

let socket;
try {
  let targets;
  for (let i = 0; i < 80; i++) {
    try {
      targets = await (await fetch('http://127.0.0.1:9224/json')).json();
      if (targets.some((target) => target.type === 'page')) break;
    } catch {}
    await delay(250);
  }
  const page = targets?.find((target) => target.type === 'page');
  if (!page) throw new Error('Chromium page target did not start');
  socket = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    socket.addEventListener('open', resolve, { once: true });
    socket.addEventListener('error', reject, { once: true });
  });
  let id = 0;
  const pending = new Map();
  const exceptions = [];
  socket.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.method === 'Runtime.exceptionThrown') {
      exceptions.push(msg.params.exceptionDetails.exception?.description
        || msg.params.exceptionDetails.text);
    }
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  });
  const send = (method, params = {}) => new Promise((resolve) => {
    const commandId = ++id;
    pending.set(commandId, resolve);
    socket.send(JSON.stringify({ id: commandId, method, params }));
  });
  await send('Runtime.enable');
  await delay(1600);

  const result = await send('Runtime.evaluate', {
    expression: `(() => {
      const d = window.__nightsDebug;
      if (!d) return { error: 'dev debug API missing' };
      const out = { steps: [] };
      const tapAt = (x, y) => {
        const opts = { pointerId: 9, clientX: x, clientY: y, pointerType: 'mouse', button: 0, bubbles: true };
        window.dispatchEvent(new PointerEvent('pointerdown', opts));
        window.dispatchEvent(new PointerEvent('pointerup', opts));
      };
      const pointOf = (obj, dy = 1) => {
        d.camera.updateMatrixWorld(true);
        const p = obj.position.clone();
        p.y += dy;
        p.project(d.camera);
        return { x: (p.x * 0.5 + 0.5) * innerWidth, y: (-p.y * 0.5 + 0.5) * innerHeight, z: p.z };
      };
      const grab = (type) => {
        const item = d.spawnGroundItem(type, d.player.position.x, d.player.position.z, { pickupDelay: 0 });
        item.landed = true;
        item.mesh.position.y = item.groundY + item.restY;
        d.pickUpItem(item);
        d.updateHud();
        return item;
      };
      const face = (x, z, pitch = -0.08) => {
        d.state.cameraYaw = Math.atan2(x - d.player.position.x, z - d.player.position.z);
        d.state.cameraPitch = pitch;
        d.cameraInitialized = false;
        d.updateCamera(0.016);
      };

      d.startGame();
      out.steps.push({ start: d.state.started === true });

      // --- Grinder: five logs and one iron, using the Drop action.
      const g = d.grinder.position;
      d.player.position.set(g.x - 1.6, d.getGroundHeight(g.x - 1.6, g.z - 1.6), g.z - 1.6);
      d.updateHud();
      grab('wood');
      const grinderLabel = document.getElementById('dropBtn').querySelector('span').textContent;
      out.grinderLabel = grinderLabel;
      for (let i = 0; i < 5; i++) {
        if (!d.state.heldItem && i > 0) break;
        d.dropCarriedItems();
        if (i < 4) grab('wood');
      }
      out.stockAfterLogs = { ...d.benchState.stock };
      grab('iron');
      d.dropCarriedItems();
      out.stockAfterIron = { ...d.benchState.stock };

      // --- Tap the bench model (not the debug API) to open the crafting panel.
      d.player.position.set(2.15, d.getGroundHeight(2.15, 2.15), 2.15);
      d.state.equippedTool = null;
      face(d.bench.position.x, d.bench.position.z, -0.05);
      d.updateCamera(0.016);
      const benchPoint = pointOf(d.bench, 1.0);
      out.benchTapPoint = benchPoint;
      tapAt(benchPoint.x, benchPoint.y);
      out.benchTapOpenedPanel = !document.getElementById('craftPanel').classList.contains('hidden');
      out.benchPromptHiddenWhileOpen = document.getElementById('benchPrompt').classList.contains('hidden');

      // --- Craft the Pickaxe through the real cards and CRAFT button.
      const pickCard = document.querySelector('.craft-card[data-recipe="pickaxe"]');
      pickCard.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true }));
      const selected = pickCard.classList.contains('selected');
      document.getElementById('craftButton').dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true }));
      out.pickaxe = {
        selected,
        crafted: d.state.ownedTools.pickaxe === true,
        stock: { ...d.benchState.stock },
        badgeTexts: [...document.querySelectorAll('.craft-card-badge')]
          .filter((badge) => badge.style.display !== 'none')
          .map((badge) => badge.textContent)
      };
      d.closeCraftPanel();

      // --- Feed two logs at 50 progress: 50 + 30 + 30 = level 2, reset to 50.
      const c = d.campfire.position;
      d.player.position.set(c.x + 1.7, d.getGroundHeight(c.x + 1.7, c.z), c.z);
      d.updateHud();
      d.state.fireLevel = 1;
      d.state.fireProgress = 50;
      d.state.fireOut = false;
      grab('wood');
      out.fireLabel = document.getElementById('dropBtn').querySelector('span').textContent;
      d.dropCarriedItems();
      grab('wood');
      d.dropCarriedItems();
      out.afterFeeding = {
        level: d.state.fireLevel,
        progress: Math.round(d.state.fireProgress),
        text: document.getElementById('fireCounterText').textContent
      };

      // --- Tapping the fire must not feed it.
      grab('wood');
      const progressBeforeTap = d.state.fireProgress;
      face(c.x, c.z, -0.3);
      d.updateCamera(0.016);
      const firePoint = pointOf(d.campfire, 1.0);
      tapAt(firePoint.x, firePoint.y);
      out.fireTap = {
        fedNothing: Math.abs(d.state.fireProgress - progressBeforeTap) < 0.001,
        stillHolding: !!d.state.heldItem
      };
      d.dropCarriedItems();
      d.state.fireOut = false;
      d.state.fireProgress = 0.05;
      d.updateCampfire(1);
      out.drain = {
        level: d.state.fireLevel,
        progress: d.state.fireProgress,
        out: d.state.fireOut,
        warningVisible: document.getElementById('fireWarning').classList.contains('visible'),
        counterText: document.getElementById('fireCounterText').textContent
      };
      // Relight with one more log and confirm the level persisted.
      grab('wood');
      d.dropCarriedItems();
      out.relight = {
        level: d.state.fireLevel,
        out: d.state.fireOut,
        progress: Math.round(d.state.fireProgress)
      };
      out.startHint = {
        text: document.getElementById('startHint').textContent.trim(),
        visible: document.getElementById('startHint').classList.contains('visible')
      };
      return out;
    })()`,
    returnByValue: true
  });

  const value = result.result?.result?.value ?? result;
  console.log(JSON.stringify({ result: value, exceptions }, null, 2));
} finally {
  socket?.close();
  chrome.kill('SIGTERM');
}

