import { chromium } from 'playwright-core';

const EXE = '/home/runner/.cache/ms-playwright/chromium-1255/chrome-linux64/chrome';
const URL = process.env.GAME_URL || 'http://localhost:5173/';

const browser = await chromium.launch({ executablePath: EXE, headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1000, height: 560 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

await page.goto(URL, { waitUntil: 'networkidle' });
await page.waitForFunction(() => !!window.__nightsDebug, null, { timeout: 15000 });
await page.click('#startBtn');
await page.waitForTimeout(600);

const results = [];
const log = (name, ok, detail) => { results.push({ name, ok, detail }); console.log((ok ? 'PASS ' : 'FAIL ') + name + (detail ? ' :: ' + detail : '')); };

// --- 1. Dragging follows the camera's right side across a full rotation ---
await page.evaluate(() => {
  const d = window.__nightsDebug;
  const px = d.player.position.x;
  const pz = d.player.position.z;
  const item = d.spawnGroundItem('wood', px + 0.5, pz, {
    startY: d.player.position.y + 0.5, velocityY: 0, pickupDelay: 0
  });
  item.landed = true;
  d.pickUpItem(item);
});

const samples = [];
for (let step = 0; step < 8; step += 1) {
  await page.evaluate((yaw) => { window.__nightsDebug.state.cameraYaw = yaw; }, (step / 8) * Math.PI * 2);
  await page.waitForTimeout(260);
  const s = await page.evaluate(() => {
    const d = window.__nightsDebug;
    const item = d.groundItems.find((i) => i.carried);
    const cam = d.camera;
    cam.updateMatrixWorld();
    const pos = item.mesh.position;
    const v = pos.clone().sub(d.player.position);
    const right = new pos.constructor(-Math.cos(d.state.cameraYaw), 0, Math.sin(d.state.cameraYaw));
    const rightDot = v.dot(right);
    const proj = pos.clone().project(cam);
    const screenX = (proj.x * 0.5 + 0.5) * window.innerWidth;
    const label = document.getElementById('dragLabel');
    const rect = label.getBoundingClientRect();
    return {
      rightDot,
      screenX,
      centerX: window.innerWidth / 2,
      horizontalDist: Math.hypot(v.x, v.z),
      labelVisible: label.classList.contains('visible'),
      labelCenterX: rect.left + rect.width / 2,
      labelText: document.getElementById('dragName').textContent,
      flameCount: document.querySelectorAll('#dragFlames .drag-flame').length
    };
  });
  samples.push(s);
}
