  const level = state.fireLevel;
  const progress = clamp(state.fireProgress, 0, 100);
  const full = progress >= 99.95;
  if (level >= FIRE_LEVEL_MAX && full) {
    fireCounterText.textContent = `level ${level} progress: MAX`;
