import fs from 'node:fs';

const list = await fetch('http://127.0.0.1:9222/json/list').then((r) => r.json());
const target = list.find((t) => t.type === 'page');
if (!target) throw new Error('No page target');

const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});

let nextId = 1;
const pending = new Map();
const consoleErrors = [];
ws.addEventListener('message', (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id) {
    const entry = pending.get(msg.id);
    if (!entry) return;
    pending.delete(msg.id);
    if (msg.error) entry.reject(new Error(JSON.stringify(msg.error)));
    else entry.resolve(msg.result);
    return;
  }
  if (msg.method === 'Runtime.exceptionThrown') {
    consoleErrors.push(msg.params.exceptionDetails.text || 'exception');
  }
  if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') {
    consoleErrors.push(msg.params.args.map((a) => a.value || a.description || '').join(' '));
  }
});

function send(method, params = {}) {
  const id = nextId++;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function evaluate(expression, awaitPromise = false) {
  const result = await send('Runtime.evaluate', {
    expression,
    awaitPromise,
    returnByValue: true,
    userGesture: true
  });
  if (result.exceptionDetails) {
    throw new Error(result.exceptionDetails.text + ': ' + (result.exceptionDetails.exception?.description || ''));
  }
  return result.result.value;
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', {
  width: 1280,
  height: 720,
  deviceScaleFactor: 1,
  mobile: false
});
await send('Page.navigate', { url: 'http://127.0.0.1:4173/' });

for (let i = 0; i < 80; i += 1) {
  const ready = await evaluate('document.readyState === "complete" && !!window.__nightsDebug');
  if (ready) break;
  await sleep(150);
}

const hasDebug = await evaluate('!!window.__nightsDebug');
if (!hasDebug) {
  console.log(JSON.stringify({ ok: false, reason: 'debug missing', consoleErrors }, null, 2));
  process.exit(1);
}

await evaluate('document.getElementById("startBtn").click()');
await sleep(800);

const initial = await evaluate(`(() => {
  const d = window.__nightsDebug;
  return {
    started: d.state.started,
    fireLevel: d.state.fireLevel,
    fireProgress: d.state.fireProgress,
    fireOut: d.state.fireOut,
    fireBarVisible: d.fireBar.visible,
    safeRingVisible: !!d.safeRing() && d.safeRing().visible,
    wallRadius: d.arenaWallRadius(),
    wallHeight: d.arenaWall.children[0].scale.y,
    wallThickness: d.arenaWall.children[1].scale.x - d.arenaWall.children[0].scale.x,
    visibleEnemies: d.enemies.filter((e) => e.visible).length,
    logCount: d.campfireVisual.children.length,
    props: { well: !!d.well, pond: !!d.pond, notice: !!d.noticeBoard },
    benchDistance: Math.hypot(d.bench.position.x, d.bench.position.z),
    grinderDistance: Math.hypot(d.grinder.position.x, d.grinder.position.z),
    trees: d.forestStats.trees,
    chunks: d.forestStats.chunks
  };
})()`);

const shot1 = await send('Page.captureScreenshot', { format: 'png' });
fs.writeFileSync('/tmp/opencode/part2-initial.png', Buffer.from(shot1.data, 'base64'));

const progression = [];
for (let i = 0; i < 4; i += 1) {
  await evaluate('window.__nightsDebug.addFireProgress(30)');
  await sleep(140);
  progression.push(await evaluate(`(() => {
    const d = window.__nightsDebug;
    const ctx = d.fireBarCanvas.getContext('2d');
    const pixel = ctx.getImageData(520, 190, 1, 1).data;
    return {
      step: ${i + 1},
      level: d.state.fireLevel,
      progress: Math.round(d.state.fireProgress),
      color: d.fireBarColorFor(d.state.fireProgress),
      pixel: Array.from(pixel),
      messageTimer: Math.round(d.state.fireBarMessageTimer * 10) / 10,
      noticeVisible: d.mapExpandedNotice.classList.contains('visible'),
      noticeText: d.mapExpandedNotice.textContent.trim(),
      barVisible: d.fireBar.visible
    };
  })()`));
}

const afterLevel = await evaluate(`(() => {
  const d = window.__nightsDebug;
  return {
    level: d.state.fireLevel,
    progress: Math.round(d.state.fireProgress),
    messageTimer: d.state.fireBarMessageTimer,
    noticeVisible: d.mapExpandedNotice.classList.contains('visible'),
    wallTarget: d.wallExpansion() ? d.wallExpansion().to : d.arenaWallRadius(),
    queuedChunks: d.forestQueue.length,
    trees: d.forestStats.trees,
    chunks: d.forestStats.chunks
  };
})()`);

const shot2 = await send('Page.captureScreenshot', { format: 'png' });
