    if (rock.shake > 0) {
      rock.shake = Math.max(0, rock.shake - delta);
      const strength = rock.shake / 0.3;
      const t = performance.now() * 0.001;
      rock.group.rotation.z = Math.sin(t * 48) * 0.04 * strength;
    } else {
      rock.group.rotation.z = 0;
