import fs from 'node:fs';

export async function connect() {
  const list = await fetch('http://127.0.0.1:9222/json/list').then((r) => r.json());
  const target = list.find((t) => t.type === 'page');
  if (!target) throw new Error('No page target');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });
  let nextId = 1;
  const pending = new Map();
  const consoleErrors = [];
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id) {
      const entry = pending.get(msg.id);
      if (!entry) return;
      pending.delete(msg.id);
      if (msg.error) entry.reject(new Error(JSON.stringify(msg.error)));
      else entry.resolve(msg.result);
      return;
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      consoleErrors.push(msg.params.exceptionDetails.text || 'exception');
    }
    if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') {
      consoleErrors.push(msg.params.args.map((a) => a.value || a.description || '').join(' '));
    }
  });
  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async function evaluate(expression, awaitPromise = false) {
    const result = await send('Runtime.evaluate', {
      expression,
      awaitPromise,
      returnByValue: true,
      userGesture: true
    });
    if (result.exceptionDetails) {
      throw new Error(result.exceptionDetails.text + ': ' + (result.exceptionDetails.exception?.description || ''));
    }
    return result.result.value;
  }
  async function screenshot(path) {
    const shot = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path, Buffer.from(shot.data, 'base64'));
  }
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  return { ws, send, evaluate, screenshot, sleep, consoleErrors };
}

export async function boot(url = 'http://127.0.0.1:4173/') {
  const cdp = await connect();
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  await cdp.send('Emulation.setDeviceMetricsOverride', {
    width: 1280, height: 720, deviceScaleFactor: 1, mobile: false
  });
  await cdp.send('Page.navigate', { url });
  for (let i = 0; i < 100; i += 1) {
    const ready = await cdp.evaluate('document.readyState === "complete" && !!window.__nightsDebug');
    if (ready) break;
    await cdp.sleep(150);
  }
  return cdp;
}

import { boot } from './cdp-lib.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const cdp = await boot();
const ev = cdp.evaluate;

await ev('document.getElementById("startBtn").click()');
await sleep(900);

const snap = () => ev(`(() => {
  const d = window.__nightsDebug;
  return {
    level: d.state.fireLevel,
    progress: Math.round(d.state.fireProgress * 10) / 10,
    fireOut: d.state.fireOut,
    fireEverLit: d.state.fireEverLit,
    barVisible: d.fireBar.visible,
    barIsSprite: d.fireBar.isSprite === true,
    barY: Math.round(d.fireBar.position.y * 100) / 100,
    barScale: [d.fireBar.scale.x, d.fireBar.scale.y],
    messageTimer: Math.round(d.state.fireBarMessageTimer * 10) / 10,
    notice: d.mapExpandedNotice.classList.contains('visible'),
    wallRadius: Math.round(d.arenaWallRadius() * 100) / 100,
    innerScale: d.arenaWall.children[0].scale.x,
    outerScale: d.arenaWall.children[1].scale.x,
    wallHeight: d.arenaWall.children[0].scale.y,
    expansionActive: !!d.wallExpansion(),
    expansionTarget: d.wallExpansion() ? d.wallExpansion().to : null,
    safeRingVisible: !!d.safeRing() && d.safeRing().visible,
    safeRingRadius: d.safeRing() ? d.safeRing().geometry.attributes.position.getX(0) : null,
    enemies: d.enemies.filter((e) => e.visible).length,
    chunks: d.forestStats.chunks,
    trees: d.forestStats.trees,
    ironRocks: d.forestStats.ironRocks,
    toast: document.getElementById('toast').textContent,
    fireWarning: document.getElementById('fireWarning').classList.contains('visible')
  };
})()`);

const initial = await snap();
await cdp.screenshot('/tmp/opencode/p2-initial.png');

// --- wall visual diagnostics -------------------------------------------------
await ev(`(() => {
  const d = window.__nightsDebug;
  d.state.fogDebug = d.scene.fog.density;
  d.scene.fog.density = 0;
  d.scene.background.set(0x203040);
})()`);
await sleep(120);
await cdp.screenshot('/tmp/opencode/p2-wall-fogoff.png');
await ev(`(() => {
  const d = window.__nightsDebug;
  d.scene.fog.density = d.state.fogDebug;
})()`);
await ev(`window.__nightsDebug.scene.fog.density = window.__nightsDebug.state.fogDebug`);

const colors = await ev(`(() => {
  const d = window.__nightsDebug;
  return [0, 34, 35, 59, 60, 99, 100].map((v) => [v, d.fireBarColorFor(v)]);
})()`);

// --- four logs -----------------------------------------------------------------
const progression = [];
for (let i = 0; i < 4; i += 1) {
  await ev('window.__nightsDebug.addFireProgress(30)');
  await sleep(120);
  progression.push(await ev(`(() => {
    const d = window.__nightsDebug;
    return {
      step: ${i + 1},
      level: d.state.fireLevel,
      progress: Math.round(d.state.fireProgress),
      color: d.fireBarColorFor(d.state.fireProgress),
      messageTimer: Math.round(d.state.fireBarMessageTimer * 10) / 10,
      notice: d.mapExpandedNotice.classList.contains('visible'),
      barVisible: d.fireBar.visible,
      expansionActive: !!d.wallExpansion(),
      wallRadius: Math.round(d.arenaWallRadius() * 10) / 10
    };
  })()`));
}
await cdp.screenshot('/tmp/opencode/p2-levelup.png');

// --- wall retreat timing + frame pacing ---------------------------------------
const retreatSamples = [];
for (let i = 0; i < 40; i += 1) {
  retreatSamples.push(await ev(`(() => {
    const d = window.__nightsDebug;
    return { t: performance.now(), r: d.arenaWallRadius(), active: !!d.wallExpansion(), chunks: d.forestStats.chunks, trees: d.forestStats.trees };
  })()`));
  if (i === 2) {
    // start frame pacing sample midway through the retreat
    ev(`window.__frameProbe = new Promise((resolve) => {
      const gaps = [];
      let last = performance.now();
      const start = last;
      function tick(now) {
        gaps.push(now - last);
        last = now;
        if (now - start < 2500) requestAnimationFrame(tick);
        else {
          const s = gaps.slice(1).sort((a, b) => a - b);
          resolve({ frames: gaps.length, avg: s.reduce((a, b) => a + b, 0) / Math.max(1, s.length), max: s[s.length - 1], p95: s[Math.floor(s.length * 0.95)] });
        }
      }
      requestAnimationFrame(tick);
    })`);
  }
  await sleep(250);
}
const frameStats = await ev('window.__frameProbe', true);
const retreatEnd = await snap();
await cdp.screenshot('/tmp/opencode/p2-retreat.png');

// duration taken to settle at target
let settleMs = null;
const t0 = retreatSamples[0].t;
for (const s of retreatSamples) {
  if (!s.active && Math.abs(s.r - 250) < 0.6) { settleMs = Math.round(s.t - t0); break; }
}
const radii = retreatSamples.map((s) => Math.round(s.r * 10) / 10);
let maxStep = 0;
for (let i = 1; i < retreatSamples.length; i += 1) {
  maxStep = Math.max(maxStep, Math.abs(retreatSamples[i].r - retreatSamples[i - 1].r));
}
const chunkGrowth = retreatSamples.map((s) => s.chunks);

// --- overflow carry ------------------------------------------------------------
// At this point level 2 at 20 progress (120 -> 20).
const overflow = [];
for (let i = 0; i < 3; i += 1) {
  await ev('window.__nightsDebug.addFireProgress(30)');
  await sleep(100);
  overflow.push(await ev(`(() => {
    const d = window.__nightsDebug;
    return { level: d.state.fireLevel, progress: Math.round(d.state.fireProgress), messageTimer: Math.round(d.state.fireBarMessageTimer * 10) / 10, notice: d.mapExpandedNotice.classList.contains('visible'), target: d.wallExpansion() ? d.wallExpansion().to : null };
  })()`));
}

// --- fire going out and relighting ---------------------------------------------
const burningState = await snap();
await ev(`(() => {
  const d = window.__nightsDebug;
  d.state.fireProgress = 0.001;
  d.state.cycleTime = 1000;
  d.updateCampfire(0.5);
})()`);
await sleep(250);
const outState = await snap();
const outToastAtNight = await ev(`document.getElementById('toast').textContent`);
await ev(`(() => { window.__nightsDebug.state.fireDarken = 0; })()`);
await ev('window.__nightsDebug.addFireProgress(12)');
await sleep(250);
const relitState = await snap();

// --- monsters -------------------------------------------------------------------
await ev(`(() => {
  const d = window.__nightsDebug;
  d.state.night = 1;
  d.state.fireLevel = 2;
  d.spawnNightWave();
})()`);
await sleep(200);
const day1Enemies = await ev(`window.__nightsDebug.enemies.filter((e) => e.visible).length`);

await ev(`(() => {
  const d = window.__nightsDebug;
  d.state.night = 3;
  d.state.fireLevel = 3;
  d.spawnNightWave();
})()`);
await sleep(300);
const nightEnemies = await ev(`(() => {
  const d = window.__nightsDebug;
  const visible = d.enemies.filter((e) => e.visible);
  return {
    count: visible.length,
    maxDistance: Math.round(Math.max(...visible.map((e) => Math.hypot(e.position.x, e.position.z)))),
    wallRadius: Math.round(d.arenaWallRadius()),
    level: d.state.fireLevel,
    night: d.state.night
  };
})()`);

// --- only logs burn --------------------------------------------------------------
await ev('window.__nightsDebug.putLogInFire()');
await sleep(80);
const nonLogToast = await ev(`document.getElementById('toast').textContent`);

console.log(JSON.stringify({
  initial,
  colors,
  progression,
  retreat: { radii, settleMs, maxStep, chunkGrowth, frameStats, end: retreatEnd },
  overflow,
  fireOut: { before: burningState, out: outState, outToastAtNight, relit: relitState },
  monsters: { day1Enemies, nightEnemies },
  nonLogToast,
  consoleErrors: cdp.consoleErrors
}, null, 2));

cdp.ws.close();

