input.content:
import { boot } from './cdp-lib.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const cdp = await boot();
const ev = cdp.evaluate;

await ev('document.getElementById("startBtn").click()');
await sleep(1200);

const info = await ev(`(() => {
  const d = window.__nightsDebug;
  const v = new d.campfire.position.constructor();
  v.set(d.campfire.position.x, d.campfire.position.y + 0.6, d.campfire.position.z);
  v.project(d.camera);
  const cam = d.camera.position;
  return {
    player: [d.player.position.x, d.player.position.y, d.player.position.z],
    camera: [cam.x, cam.y, cam.z],
    fireNdc: [Math.round(v.x * 100) / 100, Math.round(v.y * 100) / 100, Math.round(v.z * 100) / 100],
    fireWarning: document.getElementById('fireWarning').classList.contains('visible'),
    fireOut: d.state.fireOut,
    fireBar: d.fireBar.visible,
    darkness: document.getElementById('darkness').style.opacity,
    wallRadius: d.arenaWallRadius(),
    treeCount: d.treeData.length,
    choppable: d.treeData.filter((t) => t.userData.choppable).length,
    calls: d.renderer.info.render.calls,
    triangles: d.renderer.info.render.triangles
  };
})()`);
await cdp.screenshot('/tmp/opencode/p3-initial.png');

async function measure(seconds) {
  return ev(`new Promise((resolve) => {
    const gaps = [];
    let last = performance.now();
    const start = last;
    function tick(now) {
      gaps.push(now - last);
      last = now;
      if (now - start < ${seconds * 1000}) requestAnimationFrame(tick);
      else {
        const s = gaps.slice(1).sort((a, b) => a - b);
        resolve({ frames: gaps.length, avg: Math.round(s.reduce((a, b) => a + b, 0) / Math.max(1, s.length) * 10) / 10, max: Math.round(s[s.length - 1] * 10) / 10, p95: Math.round(s[Math.floor(s.length * 0.95)] * 10) / 10 });
      }
    }
    requestAnimationFrame(tick);
  })`, true);
}

const perf1280 = await measure(2);
await cdp.send('Emulation.setDeviceMetricsOverride', {
  width: 640, height: 360, deviceScaleFactor: 1, mobile: false
});
await sleep(600);
const small = await ev(`(() => {
  const d = window.__nightsDebug;
  return { calls: d.renderer.info.render.calls, triangles: d.renderer.info.render.triangles, size: [d.renderer.domElement.width, d.renderer.domElement.height] };
})()`);
const perf640 = await measure(2);

console.log(JSON.stringify({ info, perf1280, small, perf640, consoleErrors: cdp.consoleErrors }, null, 2));
cdp.ws.close();

import { boot } from './cdp-lib.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const cdp = await boot();
const ev = cdp.evaluate;

await ev('document.getElementById("startBtn").click()');
await sleep(800);
await ev(`(() => {
  const d = window.__nightsDebug;
  d.player.position.set(1.3, d.getGroundHeight(1.3, -5.2), -5.2);
  d.player.rotation.y = 0;
  d.state.cameraYaw = 0;
  d.state.cameraPitch = -0.06;
})()`);
await sleep(400);

// Lit level 1 (one log) at 30 progress.
await ev('window.__nightsDebug.addFireProgress(30)');
await sleep(700);
await cdp.screenshot('/tmp/opencode/p3-fire-l1.png');

const l1 = await ev(`(() => {
  const d = window.__nightsDebug;
  return { level: d.state.fireLevel, progress: Math.round(d.state.fireProgress), flameVisible: d.campfire.children.filter((c) => c.visible).length, barVisible: d.fireBar.visible };
})()`);

// Level 2 (finish the level).
await ev('window.__nightsDebug.addFireProgress(30)');
await ev('window.__nightsDebug.addFireProgress(30)');
await ev('window.__nightsDebug.addFireProgress(30)');
await sleep(900);
await cdp.screenshot('/tmp/opencode/p3-fire-l2-message.png');

// Let the message expire and drain a little for a normal bar.
await ev(`(() => { window.__nightsDebug.state.fireBarMessageTimer = 0; window.__nightsDebug.drawFireBar(); })()`);
await sleep(200);
await cdp.screenshot('/tmp/opencode/p3-fire-l2.png');

for (const level of [3, 4, 5]) {
  await ev(`(() => {
    const d = window.__nightsDebug;
    d.state.fireLevel = ${level};
    d.state.fireProgress = ${level === 5 ? 100 : 62};
    d.state.fireOut = false;
    d.state.fireEverLit = true;
    d.state.fireBarMessageTimer = 0;
    d.buildCampfireLevel(${level});
    d.updateHud();
  })()`);
  await sleep(800);
  await cdp.screenshot(`/tmp/opencode/p3-fire-l${level}.png`);
}

const last = await ev(`(() => {
  const d = window.__nightsDebug;
  return { level: d.state.fireLevel, progress: Math.round(d.state.fireProgress), barVisible: d.fireBar.visible, safeRadius: d.getCampfireSafeRadius(), flameChildren: d.campfire.children.length };
})()`);

console.log(JSON.stringify({ l1, last, consoleErrors: cdp.consoleErrors }, null, 2));
cdp.ws.close();

