import { boot } from './cdp-lib.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const cdp = await boot();
const ev = cdp.evaluate;

await ev('document.getElementById("startBtn").click()');
await sleep(700);

await ev(`(() => {
  const d = window.__nightsDebug;
  d.player.position.set(40, d.getGroundHeight(40, 0), 0);
  d.state.cameraYaw = Math.PI / 2;
  d.state.cameraPitch = -0.02;
})()`);
await sleep(500);
await cdp.screenshot('/tmp/opencode/p3-wall-before.png');

await ev('window.__nightsDebug.addFireProgress(100)');
await sleep(150);
await cdp.screenshot('/tmp/opencode/p3-wall-early.png');
await sleep(1900);
await cdp.screenshot('/tmp/opencode/p3-wall-2s.png');
await sleep(2500);
await cdp.screenshot('/tmp/opencode/p3-wall-4s.png');
await sleep(4200);
await cdp.screenshot('/tmp/opencode/p3-wall-done.png');

const done = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    wallRadius: Math.round(d.arenaWallRadius()),
    expansion: !!d.wallExpansion(),
    chunks: d.forestStats.chunks,
    trees: d.forestStats.trees,
    rocks: d.forestStats.rocks,
    ironRocks: d.forestStats.ironRocks,
    bushes: d.forestStats.bushes,
    ponds: d.forestStats.ponds,
    children: d.forestStats.children,
    queue: d.forestQueue.length,
    noticeVisible: d.mapExpandedNotice.classList.contains('visible'),
    noticeOpacity: getComputedStyle(d.mapExpandedNotice).opacity
  };
})()`);

// Walk into the new ring and look around.
await ev(`(() => {
  const d = window.__nightsDebug;
  d.player.position.set(120, d.getGroundHeight(120, 0), 0);
  d.state.cameraYaw = Math.PI / 2;
  d.state.cameraPitch = 0.02;
})()`);
await sleep(900);
await cdp.screenshot('/tmp/opencode/p3-forest-ring.png');

const ringView = await ev(`(() => {
  const d = window.__nightsDebug;
  return { calls: d.renderer.info.render.calls, triangles: d.renderer.info.render.triangles };
})()`);

console.log(JSON.stringify({ done, ringView, consoleErrors: cdp.consoleErrors }, null, 2));
cdp.ws.close();

