import { boot } from './cdp-lib.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const cdp = await boot();
const ev = cdp.evaluate;

async function handItem(type) {
  return ev(`(() => {
    const d = window.__nightsDebug;
    const p = d.player.position;
    const item = d.spawnGroundItem('${type}', p.x + 0.4, p.z + 0.5, {
      startY: p.y + 1.0, velocityY: 0, pickupDelay: 0
    });
    const held = d.pickUpItem(item);
    return { held, type: item.type };
  })()`);
}

await ev('document.getElementById("startBtn").click()');
await sleep(900);

const start = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    level: d.state.fireLevel, progress: d.state.fireProgress, fireOut: d.state.fireOut,
    bar: d.fireBar.visible, warning: document.getElementById('fireWarning').classList.contains('visible'),
    darkness: document.getElementById('darkness').style.opacity,
    wall: d.arenaWallRadius(), enemies: d.enemies.filter((e) => e.visible).length
  };
})()`);

// Real "pick up a log, press Put in fire" path, four times.
const feed = [];
for (let i = 0; i < 4; i += 1) {
  const hand = await handItem('wood');
  await ev('window.__nightsDebug.putLogInFire()');
  await sleep(160);
  feed.push(await ev(`(() => {
    const d = window.__nightsDebug;
    return {
      hand: ${JSON.stringify(hand)},
      level: d.state.fireLevel,
      progress: Math.round(d.state.fireProgress),
      fireOut: d.state.fireOut,
      bar: d.fireBar.visible,
      messageTimer: Math.round(d.state.fireBarMessageTimer * 10) / 10,
      toast: document.getElementById('toast').textContent
    };
  })()`));
}
await cdp.screenshot('/tmp/opencode/p4-level2.png');

// Tapping the campfire is inert.
const tapResult = await ev(`(() => {
  const d = window.__nightsDebug;
  const before = d.state.fireProgress;
  const world = new d.campfire.position.constructor(0, 0.7, 0);
  d.campfire.localToWorld(world);
  world.project(d.camera);
  const x = (world.x * 0.5 + 0.5) * window.innerWidth;
  const y = (-world.y * 0.5 + 0.5) * window.innerHeight;
  d.handleWorldTap(x, y);
  return { before: Math.round(before * 100) / 100, after: Math.round(d.state.fireProgress * 100) / 100, screen: [Math.round(x), Math.round(y)] };
})()`);

// A berry is rejected.
await handItem('berry');
await ev('window.__nightsDebug.putLogInFire()');
await sleep(120);
const berryResult = await ev(`(() => {
  const d = window.__nightsDebug;
  return { level: d.state.fireLevel, progress: Math.round(d.state.fireProgress), toast: document.getElementById('toast').textContent };
})()`);

// Exactly 100 -> level up must stay lit for the 9 s message.
await ev(`(() => {
  const d = window.__nightsDebug;
  d.state.fireLevel = 2;
  d.state.fireProgress = 88;
  d.state.fireOut = false;
  d.state.fireEverLit = true;
  d.addFireProgress(12);
})()`);
await sleep(1200);
const exact100 = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    level: d.state.fireLevel,
    progress: Math.round(d.state.fireProgress * 10) / 10,
    fireOut: d.state.fireOut,
    messageTimer: Math.round(d.state.fireBarMessageTimer * 10) / 10,
    bar: d.fireBar.visible,
    warning: document.getElementById('fireWarning').classList.contains('visible')
  };
})()`);

// Fire out at night.
await ev(`(() => {
  const d = window.__nightsDebug;
  d.state.cycleTime = 220;
  d.state.fireLevel = 3;
  d.state.fireProgress = 0.02;
  d.state.fireOut = false;
  d.state.fireEverLit = true;
})()`);
await sleep(1400);
const outState = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    daylight: d.state.daylight,
    level: d.state.fireLevel,
    progress: d.state.fireProgress,
    fireOut: d.state.fireOut,
    warning: document.getElementById('fireWarning').classList.contains('visible'),
    toast: document.getElementById('toast').textContent,
    toastVisible: document.getElementById('toast').classList.contains('visible'),
    bar: d.fireBar.visible,
    safeRing: !!d.safeRing() && d.safeRing().visible,
    darkness: document.getElementById('darkness').style.opacity,
    scare: d.getFireScareRadius()
  };
})()`);
await cdp.screenshot('/tmp/opencode/p4-fire-out.png');

// Relight with a single log.
await handItem('wood');
await ev('window.__nightsDebug.putLogInFire()');
await sleep(500);
const relit = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    level: d.state.fireLevel, progress: Math.round(d.state.fireProgress), fireOut: d.state.fireOut,
    warning: document.getElementById('fireWarning').classList.contains('visible'),
    bar: d.fireBar.visible, safeRing: !!d.safeRing() && d.safeRing().visible,
    darkness: document.getElementById('darkness').style.opacity, scare: d.getFireScareRadius()
  };
})()`);

// Monsters.
await ev(`(() => { const d = window.__nightsDebug; d.state.night = 1; d.state.fireLevel = 2; d.spawnNightWave(); })()`);
await sleep(200);
const day1 = await ev('window.__nightsDebug.enemies.filter((e) => e.visible).length');
await ev(`(() => { const d = window.__nightsDebug; d.state.night = 2; d.state.fireLevel = 2; d.spawnNightWave(); })()`);
await sleep(300);
const scaling = [];
for (const [night, level] of [[2, 2], [4, 3], [6, 5]]) {
  await ev(`(() => { const d = window.__nightsDebug; d.state.night = ${night}; d.state.fireLevel = ${level}; d.spawnNightWave(); })()`);
  await sleep(220);
  scaling.push(await ev(`(() => {
    const d = window.__nightsDebug;
    const v = d.enemies.filter((e) => e.visible);
    return { night: ${night}, level: ${level}, count: v.length, maxRadius: Math.round(Math.max(0, ...v.map((e) => Math.hypot(e.position.x, e.position.z)))), wall: Math.round(d.arenaWallRadius()) };
  })()`));
}

// Prop tour looking back toward the pond and notice board.
await ev(`(() => {
  const d = window.__nightsDebug;
  d.state.cycleTime = 20;
  d.player.position.set(0.5, d.getGroundHeight(0.5, 2.5), 2.5);
  d.state.cameraYaw = Math.PI;
  d.state.cameraPitch = -0.02;
})()`);
await sleep(900);
await cdp.screenshot('/tmp/opencode/p4-props-back.png');

console.log(JSON.stringify({ start, feed, tapResult, berryResult, exact100, outState, relit, monsters: { day1, scaling }, consoleErrors: cdp.consoleErrors }, null, 2));
cdp.ws.close();

