import { boot } from './cdp-lib.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const cdp = await boot();
const ev = cdp.evaluate;

async function clearHand() {
  await ev(`(() => {
    const d = window.__nightsDebug;
    if (d.heldItem()) d.undragItem();
  })()`);
  await sleep(80);
}

async function handItem(type) {
  await clearHand();
  return ev(`(() => {
    const d = window.__nightsDebug;
    const p = d.player.position;
    const item = d.spawnGroundItem('${type}', p.x + 0.4, p.z + 0.5, {
      startY: p.y + 1.0, velocityY: 0, pickupDelay: 0
    });
    return d.pickUpItem(item);
  })()`);
}

await ev('document.getElementById("startBtn").click()');
await sleep(800);

// Light the fire first so "fire out" is meaningful.
await handItem('wood');
await ev('window.__nightsDebug.putLogInFire()');
await sleep(400);
const lit = await ev(`(() => {
  const d = window.__nightsDebug;
  return { level: d.state.fireLevel, progress: Math.round(d.state.fireProgress), fireOut: d.state.fireOut, warning: document.getElementById('fireWarning').classList.contains('visible'), safeRing: !!d.safeRing() && d.safeRing().visible };
})()`);

// Night, then drop just below zero.
await ev(`(() => {
  const d = window.__nightsDebug;
  d.state.cycleTime = 220;
  d.state.fireProgress = 0.001;
  d.state.fireOut = false;
  d.updateCampfire(0.1);
})()`);
await sleep(500);
const outImmediate = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    daylight: d.state.daylight,
    level: d.state.fireLevel,
    fireOut: d.state.fireOut,
    warning: document.getElementById('fireWarning').classList.contains('visible'),
    toast: document.getElementById('toast').textContent,
    bar: d.fireBar.visible,
    safeRing: !!d.safeRing() && d.safeRing().visible,
    darkness: document.getElementById('darkness').style.opacity,
    scare: d.getFireScareRadius()
  };
})()`);
await sleep(1400);
const outDark = await ev(`(() => {
  const d = window.__nightsDebug;
  return { darkness: document.getElementById('darkness').style.opacity, fireDarken: Math.round(d.state.fireDarken * 1000) / 1000, warning: document.getElementById('fireWarning').classList.contains('visible') };
})()`);
await cdp.screenshot('/tmp/opencode/p5-fire-out.png');

// Relight.
await handItem('wood');
await ev('window.__nightsDebug.putLogInFire()');
await sleep(600);
const relit = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    level: d.state.fireLevel,
    progress: Math.round(d.state.fireProgress),
    fireOut: d.state.fireOut,
    warning: document.getElementById('fireWarning').classList.contains('visible'),
    bar: d.fireBar.visible,
    safeRing: !!d.safeRing() && d.safeRing().visible,
    darkness: document.getElementById('darkness').style.opacity,
    scare: d.getFireScareRadius()
  };
})()`);
await cdp.screenshot('/tmp/opencode/p5-relit.png');

// Prop tour shots in daylight.
const shots = [
  ['pond', 11.5, -4.4, Math.PI, -0.05],
  ['notice', -9.6, -4.2, Math.PI, -0.03],
  ['well', -13.4, 1.8, 0.08, -0.02],
  ['bench', 5.2, 5.6, 0.62, -0.02]
];
for (const [name, x, z, yaw, pitch] of shots) {
  await ev(`(() => {
    const d = window.__nightsDebug;
    d.state.cycleTime = 20;
    d.player.position.set(${x}, d.getGroundHeight(${x}, ${z}), ${z});
    d.state.cameraYaw = ${yaw};
    d.state.cameraPitch = ${pitch};
    d.state.cameraDistance = 6.4;
  })()`);
  await sleep(700);
  await cdp.screenshot(`/tmp/opencode/p5-prop-${name}.png`);
}

console.log(JSON.stringify({ lit, outImmediate, outDark, relit, consoleErrors: cdp.consoleErrors }, null, 2));
cdp.ws.close();

import { boot } from './cdp-lib.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const cdp = await boot();
const ev = cdp.evaluate;

await ev('document.getElementById("startBtn").click()');
await sleep(600);

const measure = await ev(`(() => {
  const d = window.__nightsDebug;
  d.resetForestExpansion();
  const results = {};
  for (const level of [2, 3, 4, 5]) {
    d.resetForestExpansion();
    d.ensureForestRingQueued(level);
    const jobs = d.forestQueue.length;
    const times = [];
    let chunkTimes = [];
    for (let i = 0; i < jobs; i += 1) {
      const job = d.forestQueue.shift();
      const t0 = performance.now();
      d.buildForestChunk(job);
      chunkTimes.push(performance.now() - t0);
    }
    chunkTimes.sort((a, b) => a - b);
    results[level] = {
      chunks: jobs,
      totalMs: Math.round(chunkTimes.reduce((a, b) => a + b, 0)),
      maxMs: Math.round(chunkTimes[chunkTimes.length - 1] * 10) / 10,
      p95Ms: Math.round(chunkTimes[Math.floor(chunkTimes.length * 0.95)] * 10) / 10,
      medianMs: Math.round(chunkTimes[Math.floor(chunkTimes.length / 2)] * 10) / 10,
      stats: { ...d.forestStats }
    };
  }
  d.resetForestExpansion();
  return results;
})()`);

console.log(JSON.stringify({ measure, consoleErrors: cdp.consoleErrors }, null, 2));
cdp.ws.close();

import { boot } from './cdp-lib.mjs';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const cdp = await boot();
const ev = cdp.evaluate;

await ev('document.getElementById("startBtn").click()');
await sleep(700);

// Clamp test before and after expansion.
const clampBefore = await ev(`(() => {
  const d = window.__nightsDebug;
  const p = new d.player.position.constructor(100, 0, 0);
  d.clampToArena(p, 1);
  return { x: Math.round(p.x * 10) / 10, z: Math.round(p.z * 10) / 10 };
})()`);

// Position near the wall, look at it, and trigger expansion to see dust.
await ev(`(() => {
  const d = window.__nightsDebug;
  d.player.position.set(42, d.getGroundHeight(42, 0), 0);
  d.state.cameraYaw = Math.PI / 2;
  d.state.cameraPitch = -0.02;
})()`);
await sleep(500);
await ev('window.__nightsDebug.addFireProgress(100)');
await sleep(420);
await cdp.screenshot('/tmp/opencode/p6-dust.png');

// Message timing: visible ~9s then reverts.
const msgEarly = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    messageTimer: Math.round(d.state.fireBarMessageTimer * 10) / 10,
    notice: d.mapExpandedNotice.classList.contains('visible'),
    noticeOpacity: getComputedStyle(d.mapExpandedNotice).opacity,
    progress: Math.round(d.state.fireProgress),
    level: d.state.fireLevel
  };
})()`);
await sleep(8600);
const msgLate = await ev(`(() => {
  const d = window.__nightsDebug;
  return {
    messageTimer: Math.round(d.state.fireBarMessageTimer * 10) / 10,
    notice: d.mapExpandedNotice.classList.contains('visible'),
    noticeOpacity: getComputedStyle(d.mapExpandedNotice).opacity,
    fireOut: d.state.fireOut,
    progress: Math.round(d.state.fireProgress * 10) / 10,
    wall: Math.round(d.arenaWallRadius()),
    expansion: !!d.wallExpansion()
  };
})()`);
await cdp.screenshot('/tmp/opencode/p6-after-message.png');

// Clamp after expansion.
const clampAfter = await ev(`(() => {
  const d = window.__nightsDebug;
  const p = new d.player.position.constructor(1000, 0, 0);
  d.clampToArena(p, 1);
  return { x: Math.round(p.x * 10) / 10, wall: d.arenaWallRadius() };
})()`);

console.log(JSON.stringify({ clampBefore, msgEarly, msgLate, clampAfter, consoleErrors: cdp.consoleErrors }, null, 2));
cdp.ws.close();

