  rightArm.rotation.set(0, 0, 0);
  leftLeg.rotation.set(0, 0, 0);
  rightLeg.rotation.set(0, 0, 0);
  deathBanner.classList.remove('visible');
  hideHitMeter();

  state.cycleTime = DAY_LENGTH;
  state.nightActive = true;
  spawnNightWave();
