input.content:
import { openPage, wait } from './cdp.mjs';

const page = await openPage('http://127.0.0.1:5173/');
const evalx = page.evaluate;

await evalx(`(() => { window.__nightsDebug.startGame(); return true; })()`);
await wait(900);

const results = {};

// 1. Starting arena.
results.start = await evalx(`(() => {
  const d = window.__nightsDebug;
  const s = d.state;
  return {
    arenaRadius: d.arenaWallRadius(),
    wallHeight: d.arenaWall.children[0].scale.y,
    wallThickness: d.arenaWall.children[1].scale.x - d.arenaWall.children[0].scale.x,
    unlit: s.fireOut && !s.fireEverLit,
    level: s.fireLevel,
    progress: s.fireProgress,
    logs: d.campfireVisual.children.length,
    barVisible: d.fireBar.visible,
    safeRingVisible: d.safeRing() ? d.safeRing().visible : null,
    playerDistance: Math.hypot(d.player.position.x, d.player.position.z)
  };
})()`);

// 2. Only logs burn; a berry must not feed the fire.
results.onlyLogs = await evalx(`(() => {
  const d = window.__nightsDebug;
  const p = d.player.position;
  const berry = d.spawnGroundItem('berry', p.x + 0.3, p.z + 0.3, { pickupDelay: 0 });
  d.pickUpItem(berry);
  const before = d.state.fireProgress;
  d.putLogInFire();
  return {
    heldType: d.heldItem() ? d.heldItem().type : null,
    progressBefore: before,
    progressAfter: d.state.fireProgress,
    stillHeld: !!d.heldItem(),
    toast: document.querySelector('.toast')?.textContent || null
  };
})()`);

// 3. Four logs -> level 2, 20 overflow, wall expands 200 m, forest grows.
const feedSteps = [];
for (let i = 0; i < 4; i += 1) {
  feedSteps.push(await evalx(`(() => {
    const d = window.__nightsDebug;
    const p = d.player.position;
    const item = d.spawnGroundItem('wood', p.x + 0.4, p.z + 0.4, { pickupDelay: 0 });
    d.pickUpItem(item);
    d.putLogInFire();
    const s = d.state;
    return {
      level: s.fireLevel,
      progress: Number(s.fireProgress.toFixed(2)),
      messageTimer: Number(s.fireBarMessageTimer.toFixed(2)),
      barVisible: d.fireBar.visible,
      wallExpanding: !!d.wallExpansion(),
      queue: d.forestQueue.length,
      chunks: d.forestStats.chunks
    };
  })()`));
  await wait(180);
}
await wait(600);
results.feed = feedSteps;
results.levelUp = await evalx(`(() => {
  const d = window.__nightsDebug;
  return {
    level: d.state.fireLevel,
    progress: Number(d.state.fireProgress.toFixed(2)),
    messageTimer: Number(d.state.fireBarMessageTimer.toFixed(2)),
    noticeVisible: d.mapExpandedNotice.classList.contains('visible'),
    noticeText: d.mapExpandedNotice.textContent.trim().replace(/\\s+/g, ' '),
    barVisible: d.fireBar.visible,
    safeRingVisible: d.safeRing() ? d.safeRing().visible : null,
    from: d.wallExpansion()?.from,
    to: d.wallExpansion()?.to,
    fogDensity: Number(d.scene.fog.density.toFixed(5))
  };
})()`);

// 4. Measure frame pacing during the chunked forest build.
const frameStats = await evalx(`new Promise((resolve) => {
  const times = [];
  let last = performance.now();
  let frames = 0;
  function tick(now) {
    times.push(now - last);
    last = now;
    frames += 1;
    if (frames < 180) requestAnimationFrame(tick);
    else {
      const sorted = times.slice().sort((a, b) => a - b);
      resolve({
        frames,
        avg: Number((times.reduce((a, b) => a + b, 0) / times.length).toFixed(2)),
        p95: Number(sorted[Math.floor(sorted.length * 0.95)].toFixed(2)),
        max: Number(sorted[sorted.length - 1].toFixed(2)),
        chunks: window.__nightsDebug.forestStats.chunks,
        trees: window.__nightsDebug.forestStats.trees
      });
    }
  }
  requestAnimationFrame(tick);
})`);

await wait(7800);
results.expanded = await evalx(`(() => {
  const d = window.__nightsDebug;
  return {
    wallRadius: Number(d.arenaWallRadius().toFixed(2)),
    expanding: !!d.wallExpansion(),
    chunks: d.forestStats.chunks,
    trees: d.forestStats.trees,
    queue: d.forestQueue.length,
    fogDensity: Number(d.scene.fog.density.toFixed(5)),
    safeRadius: d.getCampfireSafeRadius()
  };
})()`);

// 5. Fire-out and relight keep the level.
results.fireOut = await evalx(`(() => {
  const d = window.__nightsDebug;
  d.state.fireProgress = 0;
  d.state.fireOut = true;
  d.state.fireDarken = 0.4;
  d.updateCampfire(0.016);
  const out = {
    level: d.state.fireLevel,
    barVisible: d.fireBar.visible,
    safeRingVisible: d.safeRing() ? d.safeRing().visible : null,
    warningVisible: document.getElementById('fire-warning')?.classList.contains('visible') ?? null
  };
  d.addFireProgress(2);
  d.updateCampfire(0.016);
  return {
    out,
    relit: {
      level: d.state.fireLevel,
      progress: d.state.fireProgress,
      fireOut: d.state.fireOut,
      barVisible: d.fireBar.visible,
      safeRingVisible: d.safeRing() ? d.safeRing().visible : null
    }
  };
})()`);

// 6. All wall radii and forest queue growth.
results.radii = await evalx(`(() => {
  const d = window.__nightsDebug;
  const rows = [];
  for (let level = 1; level <= 5; level += 1) {
    d.beginWallExpansion(level);
    d.updateArenaWall(8.2);
    rows.push({
      level,
      radius: Number(d.arenaWallRadius().toFixed(2)),
      expanding: !!d.wallExpansion(),
      queue: d.forestQueue.length
    });
  }
  return rows;
})()`);

// Build every queued ring so the density growth is real, then report.
results.forestAll = await evalx(`(() => {
  const d = window.__nightsDebug;
  let guard = 0;
  while (d.forestQueue.length && guard < 500) {
    d.buildForestChunk(d.forestQueue.shift());
    guard += 1;
  }
  return {
    chunks: d.forestStats.chunks,
    trees: d.forestStats.trees,
    rocks: d.forestStats.rocks,
    ironRocks: d.forestStats.ironRocks,
    bushes: d.forestStats.bushes,
    ponds: d.forestStats.ponds,
    children: d.forestStats.children,
    queue: d.forestQueue.length
  };
})()`);

// 7. Monsters: none on night 1, scaled later, all inside the current wall.
results.monsters = await evalx(`(() => {
  const d = window.__nightsDebug;
  d.state.night = 1;
  d.state.fireLevel = 1;
  d.spawnNightWave();
  const day1 = d.enemies.filter((e) => e.visible).length;
  d.state.night = 2;
  d.state.fireLevel = 2;
  d.spawnNightWave();
  const night2 = d.enemies.filter((e) => e.visible).length;
  const inside2 = d.enemies.filter((e) => e.visible
